import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {performance} from 'node:perf_hooks';
import {parseTestEvidence,sourceSnapshot} from './conform-proof.mjs';

const root=path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const outIndex=process.argv.indexOf('--out');
const out=outIndex>=0?path.resolve(process.argv[outIndex+1]):path.join(os.tmpdir(),'architecture-manager-conform');
fs.mkdirSync(out,{recursive:true});
const steps=[
  ['lint',[path.join(root,'node_modules/eslint/bin/eslint.js'),'src','scripts']],
  ['preload',[path.join(root,'scripts/generate-preload.mjs'),'--check']],
  ['tests',['--test','--test-reporter=tap','--test-concurrency=1']]
];
const proofIndex=process.argv.indexOf('--release-proof');
if(proofIndex>=0) steps.push(['release-proof',[path.join(root,'scripts/release-proof.mjs'),path.resolve(process.argv[proofIndex+1])]]);
const workspaceIndex=process.argv.indexOf('--workspace');
if(workspaceIndex>=0) steps.push(['workspace-audit',[path.join(root,'scripts/audit-workspace.mjs'),'--workspace',path.resolve(process.argv[workspaceIndex+1]),'--out',path.join(out,'workspace-audit.json')]]);
const results=[];
const sourcesBefore=sourceSnapshot(root);
for(const [name,args] of steps) {
  const start=performance.now();
  const result=spawnSync(process.execPath,args,{cwd:root,env:process.env,encoding:'utf8',windowsHide:true,maxBuffer:64*1024*1024,timeout:600000});
  fs.writeFileSync(path.join(out,name+'.stdout'),result.stdout || '');fs.writeFileSync(path.join(out,name+'.stderr'),result.stderr || '');
  const row={name,ok:result.status===0,durationMs:performance.now()-start,exitCode:result.status,error:result.error?.message || null};
  if(name==='tests') { const evidence=parseTestEvidence(result.stdout);Object.assign(row,evidence);row.ok &&=evidence.valid; }
  results.push(row);console.log(JSON.stringify(row));
  if(!row.ok) break;
}
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const sources=sourceSnapshot(root);
const sourceStable=JSON.stringify(sourcesBefore)===JSON.stringify(sources);
const report={schema:'architecture-manager-conform/v1',evidenceVersion:2,recordedAt:new Date().toISOString(),ok:sourceStable && results.length===steps.length && results.every(row=>row.ok),results,sources,sourceStable,node:process.version,implementationComplete:false};
report.digest=sha(JSON.stringify({ok:report.ok,results:results.map(({durationMs,...row})=>row),sources}));
fs.writeFileSync(path.join(out,'conform.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({ok:report.ok,digest:report.digest,evidence:out}));
if(!report.ok) process.exitCode=1;

// One-command verification digest (3.5.0 P12). Runs the test battery plus
// read-only readbacks against the real workspace and prints a sha256 digest
// over the machine-checkable results. Re-running must reproduce the digest
// for unchanged inputs.
import { execFileSync, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { listRunLedger } from '../src/runs.mjs';
import { readDefectBook, verifyDefectBook } from '../src/defects.mjs';
import { inspectInbox } from '../src/inbox.mjs';
import { inspectGit } from '../src/git.mjs';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const workspaceRoot = process.argv[2] || 'E:/ai';
const results = { schema: 'architecture-manager-verify/v1', generatedAt: new Date().toISOString(), workspaceRoot };

const testRun = spawnSync(process.execPath, ['--test'], { cwd: repoRoot, encoding: 'utf8', timeout: 300000, shell: false });
results.tests = { exitCode: testRun.status, pass: /ℹ pass (\d+)/.exec(testRun.stdout)?.[1] ?? null, fail: /ℹ fail (\d+)/.exec(testRun.stdout)?.[1] ?? null };

const ledger = listRunLedger(workspaceRoot);
results.runs = { totalRuns: ledger.totalRuns, totals: ledger.totals, unknownSchema: ledger.platforms.flatMap((p) => p.runs).filter((r) => r.lockStatus === 'unknown-schema').length };
const book = readDefectBook(workspaceRoot);
const checker = verifyDefectBook(workspaceRoot);
results.defectBook = { total: book.total ?? null, redRows: book.redRows?.length ?? null, checkerPassed: checker.passed === true };
const inbox = inspectInbox(workspaceRoot);
results.inbox = Object.fromEntries(inbox.zones.map((zone) => [zone.zone, zone.entryCount]));
const git = inspectGit(workspaceRoot);
results.git = { isRepository: git.isRepository, branch: git.branch, head: git.head ? git.head.slice(0, 12) : null, changed: git.status.length };

const digestInput = JSON.stringify({ tests: results.tests, runs: results.runs, defectBook: results.defectBook, inbox: results.inbox });
results.digest = createHash('sha256').update(digestInput).digest('hex');

const outDir = mkdtempSync(join(tmpdir(), 'am-verify-'));
const reportPath = join(outDir, 'verify-report.json');
writeFileSync(reportPath, JSON.stringify(results, null, 1));
console.log(JSON.stringify({ digest: results.digest, tests: results.tests, runs: results.runs.totalRuns, redRows: results.defectBook.redRows, reportPath }, null, 1));
if (results.tests.fail !== '0' || results.defectBook.checkerPassed !== true) process.exit(1);

import { existsSync, readFileSync, realpathSync, statSync } from 'node:fs';
import { isAbsolute, join, relative, resolve, sep } from 'node:path';

import { sha256 } from './core/hash.mjs';
import {readJson as readJsonFile,parseJson} from './core/json.mjs';
import {targetPath} from './core/paths.mjs';
import {validateRegistry} from './domains/resources/registry.mjs';

const ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function readJson(path) {
  try { return readJsonFile(path); } catch { return null; }
}

function safeWorkspacePath(root, relativePath) {
  return targetPath(root,relative(resolve(root),resolve(root,relativePath)));
}

function toRelative(root, target) {
  return relative(root, target).split(sep).join('/');
}

function registryInfo(kind) {
  if (kind === 'agent') return { relativePath: 'agent/registry.json', key: 'agents', base: 'agent' };
  if (kind === 'skill') return { relativePath: 'tool/registry.json', key: 'skills', base: 'tool' };
  if (kind === 'workflow') return { relativePath: 'tool/registry.json', key: 'workflows', base: 'tool' };
  throw new Error('INVALID_CATALOG_KIND');
}

export function readCatalogEntry({ workspaceRoot, kind, id }) {
  if (!ID.test(String(id || ''))) throw new Error('INVALID_CATALOG_ID');
  const root = resolve(workspaceRoot);
  const info = registryInfo(kind);
  const registryPath = safeWorkspacePath(root, info.relativePath);
  const registry = readJson(registryPath);
  const entry = registry?.[info.key]?.find((item) => item.id === id);
  if (!entry) throw new Error('CATALOG_ENTRY_NOT_FOUND');
  if (kind === 'agent') {
    const currentRef = entry.current || `${id}/current.json`;
    const currentPath = safeWorkspacePath(root, currentRef.startsWith('agent/') ? currentRef : `agent/${currentRef}`);
    const current = readJson(currentPath);
    const version = current?.version || entry.version;
    const versionRoot = safeWorkspacePath(root, `agent/${id}/versions/${version}`);
    const manifestPath = join(versionRoot, 'manifest.json');
    const manifest = readJson(manifestPath);
    const promptPath = safeWorkspacePath(versionRoot, manifest?.prompt || 'prompt.md');
    return {
      kind, id, entry,
      registryPath: info.relativePath,
      currentPath: toRelative(root, currentPath),
      manifestPath: existsSync(manifestPath) ? toRelative(root, manifestPath) : null,
      promptPath: existsSync(promptPath) ? toRelative(root, promptPath) : null,
      current,
      manifest,
      prompt: existsSync(promptPath) ? readFileSync(promptPath, 'utf8') : null,
      writePerformed: false
    };
  }
  const catalogRelative = entry.path.startsWith('tool/') ? entry.path : `tool/${entry.path}`;
  const catalogPath = safeWorkspacePath(root, catalogRelative);
  const catalog = readJson(catalogPath);
  return {
    kind, id, entry,
    registryPath: info.relativePath,
    catalogPath: catalogRelative,
    catalog,
    catalogText: existsSync(catalogPath) ? readFileSync(catalogPath, 'utf8') : null,
    skillCount: Array.isArray(catalog?.skills) ? catalog.skills.length : 0,
    writePerformed: false
  };
}

export function readSkillContent({ workspaceRoot, catalogId, id, version }) {
  const detail = readCatalogEntry({ workspaceRoot, kind: 'skill', id: catalogId });
  const skill = detail.catalog?.skills?.find((item) => item.id === id && item.version === version);
  if (!skill || !ID.test(id) || !/^\d+\.\d+\.\d+(?:-[\w.-]+)?$/.test(version)) throw new Error('CATALOG_ENTRY_NOT_FOUND');
  const release = safeWorkspacePath(workspaceRoot, `tool/skills/${id}/versions/${version}`);
  const manifest = readJson(join(release, 'manifest.json'));
  const path = safeWorkspacePath(release, manifest?.entry || 'SKILL.md');
  return { id, version, path: toRelative(workspaceRoot, path), content: readFileSync(path, 'utf8'), manifest, writePerformed: false };
}

export function inspectRegistration({ workspaceRoot, kind, selectedPath }) {
  const path = safeWorkspacePath(workspaceRoot, selectedPath);
  if (kind === 'agent') {
    if (!statSync(path).isDirectory()) throw new Error('CATALOG_CURRENT_NOT_FOUND');
    const pointer = readJson(join(path, 'current.json'));
    const id = pointer?.id;
    if (!ID.test(id || '') || path !== safeWorkspacePath(workspaceRoot, `agent/${id}`)) throw new Error('INVALID_CATALOG_ID');
    if (!/^\d+\.\d+\.\d+(?:-[\w.-]+)?$/.test(pointer.version || '')) throw new Error('INVALID_CURRENT_VERSION');
    const manifest = readJson(safeWorkspacePath(path, `versions/${pointer.version}/manifest.json`));
    if (manifest?.id !== id || manifest.version !== pointer.version) throw new Error('CATALOG_MANIFEST_MISMATCH');
    return { id, entry: { current: `${id}/current.json`, version: pointer.version } };
  }
  if (kind !== 'skill') throw new Error('INVALID_CATALOG_KIND');
  const rel = toRelative(join(workspaceRoot, 'tool'), path);
  const data = readJson(path);
  if (!/^_registry\/skills-[\w.-]+\.json$/.test(rel) || !Array.isArray(data?.skills)) throw new Error('SKILL_CATALOG_PATH_REQUIRED');
  return { id: rel.split('/').pop().replace(/\.json$/, ''), entry: { path: rel } };
}

function requireUnreferenced(root, kind, id, entry) {
  const ids = kind === 'skill'
    ? [id, ...(readJson(safeWorkspacePath(root, `tool/${entry.path}`))?.skills || []).map((item) => item.id)]
    : [id];
  const referenceKeys = kind === 'agent' ? new Set(['agent', 'agents', 'agentId', 'worker', 'workers', 'outputWorker', 'delegateAgent', 'subagent']) : new Set(['skill', 'skills', 'skillId', 'skillIds']);
  const named = (value) => ids.some((target) => value === target || value.startsWith(`${kind}:${target}@`) || value === `${kind}:${target}`);
  function hasStructuredReference(node, key = '') {
    if (typeof node === 'string') return referenceKeys.has(key) && named(node);
    if (Array.isArray(node)) return node.some((item) => hasStructuredReference(item, key));
    if (!node || typeof node !== 'object') return false;
    if (referenceKeys.has(key) && Object.keys(node).some(named)) return true;
    return Object.entries(node).some(([next, value]) => hasStructuredReference(value, next));
  }
  function mentionsReference(path) {
    const text = readFileSync(path, 'utf8');
    try { return hasStructuredReference(parseJson(text)); }
    catch {
      return text.split(/\r?\n/).some((line) => {
        const match = /^\s*(?:-\s*)?([A-Za-z][A-Za-z0-9_-]*)\s*:\s*(.*)$/.exec(line);
        if (!match || !referenceKeys.has(match[1])) return false;
        return match[2].replace(/[\[\],]/g, ' ').split(/\s+/).some((token) => named(token.replace(/^['"]|['"]$/g, '')));
      });
    }
  }
  const hits = [];
  for (const [repo, key, names] of [['agent', 'agents', ['manifest.json', 'tool-lock.json']], ['tool', 'workflows', ['manifest.json', 'workflow.yaml']]]) {
    const registry = readJson(join(root, repo, 'registry.json'));
    for (const resource of registry?.[key] || []) {
      if (!resource?.id || resource.enabled === false || resource.deprecated === true) continue;
      if (kind === 'agent' && repo === 'agent' && resource.id === id) continue;
      const current = readJson(join(root, repo, resource.id, 'current.json'));
      if (!/^\d+\.\d+\.\d+(?:-[\w.-]+)?$/.test(current?.version || '')) continue;
      const release = safeWorkspacePath(root, `${repo}/${resource.id}/versions/${current.version}`);
      for (const name of names) {
        const path = join(release, name);
        if (!existsSync(path) || !statSync(path).isFile()) continue;
        if (mentionsReference(path)) hits.push(toRelative(root, path));
      }
    }
  }
  if (hits.length) throw new Error(`RESOURCE_REFERENCED: ${hits.join(', ')}`);
}

export function buildRegistryPlan({ workspaceRoot, kind, action, id, baselineSha256, entry = {}, now = new Date().toISOString() }) {
  const root = resolve(workspaceRoot);
  const info = registryInfo(kind);
  const registryPath = safeWorkspacePath(root, info.relativePath);
  if (!existsSync(registryPath)) throw new Error('CATALOG_REGISTRY_NOT_FOUND');
  const before = readFileSync(registryPath, 'utf8');
  const actualSha = sha256(before);
  if (typeof baselineSha256 !== 'string' || baselineSha256 !== actualSha) throw new Error('CATALOG_BASELINE_MISMATCH');
  const registry = parseJson(before);
  const items = Array.isArray(registry[info.key]) ? [...registry[info.key]] : [];
  const index = items.findIndex((item) => item.id === id);
  let nextItems;
  let description;
  if (action === 'add') {
    if (!ID.test(String(id || '')) || index >= 0) throw new Error('CATALOG_ENTRY_ALREADY_EXISTS');
    if (kind === 'agent') {
      const inspected = inspectRegistration({ workspaceRoot: root, kind, selectedPath: `agent/${id}` });
      nextItems = [...items, { id, ...inspected.entry, enabled: true }];
    } else {
      const catalogPath = typeof entry.path === 'string' ? entry.path : '';
      if (!catalogPath.startsWith('_registry/') || !catalogPath.endsWith('.json')) throw new Error('SKILL_CATALOG_PATH_REQUIRED');
      inspectRegistration({ workspaceRoot: root, kind, selectedPath: `tool/${catalogPath}` });
      nextItems = [...items, { id, path: catalogPath, kind: 'skill-catalog', enabled: true, invocable: false }];
    }
    description = `添加 ${kind} ${id}`;
  } else if (action === 'remove') {
    if (index < 0) throw new Error('CATALOG_ENTRY_NOT_FOUND');
    requireUnreferenced(root, kind, id, items[index]);
    nextItems = items.filter((item) => item.id !== id);
    description = `从 registry 移除 ${kind} ${id}（不删除已发布目录）`;
  } else if (action === 'mark') {
    if (index < 0) throw new Error('CATALOG_ENTRY_NOT_FOUND');
    const supersededBy = typeof entry.supersededBy === 'string' && entry.supersededBy.trim() !== '' ? entry.supersededBy : null;
    if (!supersededBy) throw new Error('CATALOG_SUPERSEDED_BY_REQUIRED');
    const deprecationNote = typeof entry.deprecationNote === 'string' ? entry.deprecationNote : null;
    nextItems = items.map((item) => item.id === id ? { ...item, deprecated: true, supersededBy, ...(deprecationNote ? { deprecationNote } : {}) } : item);
    description = `标记 ${kind} ${id} 为 deprecated（supersededBy=${supersededBy}）；不改 enabled，已钉版的 run 仍可解析`;
  } else if (action === 'enable' || action === 'disable') {
    if (index < 0) throw new Error('CATALOG_ENTRY_NOT_FOUND');
    if (action === 'disable') requireUnreferenced(root, kind, id, items[index]);
    nextItems = items.map((item) => item.id === id ? { ...item, enabled: action === 'enable' } : item);
    description = `${action === 'enable' ? '启用' : '停用'} ${kind} ${id}`;
  } else {
    throw new Error('INVALID_CATALOG_ACTION');
  }
  const afterObject = { ...registry, ...(Number.isInteger(registry.version) ? { version: registry.version + 1 } : {}), [info.key]: nextItems };
  const after = `${JSON.stringify(afterObject, null, 2)}\n`;
  validateRegistry(root,info.base,after,{validateReleases:action==='add'||action==='enable',onlyIds:new Set([id])});
  return {
    schema: 'architecture-manager-plan/v1',
    planId: `registry-${kind}-${action}-${now.replace(/[^0-9]/g, '').slice(0, 17)}`,
    kind: 'registry-edit',
    workspaceRoot: root,
    generatedAt: now,
    applyMode: 'confirmation-required',
    writePerformed: false,
    target: { path: info.relativePath, catalogKind: kind, action, id, description, entry },
    steps: [{ operation: 'replace-registry-json', target: info.relativePath, oldSha256: actualSha, newSha256: sha256(after), checkpoint: true }],
    verification: ['re-read registry baseline before apply', 'preserve checkpoint for rollback', 're-scan full catalog after apply'],
    payload: { afterText: after }
  };
}

import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';
import { runtimeFile } from './runtime-path.mjs';

export function runOwnedProcess({ python, executable = python, args, input = null, cwd, scopeRoot = cwd, timeout = 120000, env = process.env, registerCancel = () => {}, onOutput = () => {} }) {
  if (!python || !existsSync(python)) throw new Error('RUNTIME_PYTHON_REQUIRED');
  mkdirSync(cwd, { recursive: true });
  const cancelPath = join(cwd, `cancel-${randomUUID()}.flag`);
  const child = spawn(python, ['-B', runtimeFile('job_controller.py')], { cwd, windowsHide: true, shell: false, env: { ...env, PYTHONIOENCODING: 'utf-8', PYTHONDONTWRITEBYTECODE: '1' } });
  registerCancel(() => { writeFileSync(cancelPath, 'cancel'); });
  let stdout = ''; let stderr = '';
  child.stdout.on('data', (data) => { stdout += data.toString('utf8'); onOutput(data.toString('utf8')); if (stdout.length > 16 * 1024 * 1024) writeFileSync(cancelPath, 'output-limit'); });
  child.stderr.on('data', (data) => { stderr += data.toString('utf8'); if (stderr.length > 16 * 1024 * 1024) writeFileSync(cancelPath, 'output-limit'); });
  child.stdin.end(JSON.stringify({ argv: [executable, ...args], input, cwd, scopeRoot, cancelPath, timeoutSeconds: timeout / 1000 }) + '\n');
  return new Promise((resolve, reject) => { child.once('error', reject); child.once('close', (exitCode) => { registerCancel(null); resolve({ stdout, stderr, exitCode, cancelled: exitCode === 125, timedOut: exitCode === 124 }); }); });
}

import {parseJson as parseJsonText} from './json.mjs';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { targetPath } from './paths.mjs';

export const PLATFORM_IDS = Object.freeze(['codex', 'dsh', 'workbuddy', 'zcode', 'doubao', 'qoder']);

export function isFormalPlatform(id) {
  return PLATFORM_IDS.includes(id);
}

const RESERVED = new Set(['tool', 'agent', 'software', 'versions', 'inbox', 'docs-site', 'architecture-manager']);
export function validPlatformId(id) { return typeof id === 'string' && /^[a-z][a-z0-9-]{1,30}$/.test(id) && !RESERVED.has(id); }
export function isRegisteredPlatform(id, workspaceRoot) { return validPlatformId(id) && (isFormalPlatform(id) || discoverPlatformIds(workspaceRoot).includes(id)); }

// Data-driven platform list (3.5.0 P7): the six base platforms plus any
// first-level directory that carries its own bridge.json. Registered extras
// need no code change.
export function discoverPlatformIds(workspaceRoot) {
  if (!workspaceRoot || !existsSync(workspaceRoot)) return [];
  const discovered = [];
  for (const entry of readdirSync(workspaceRoot, { withFileTypes: true })) {
    if (!entry.isDirectory() || isFormalPlatform(entry.name) || !validPlatformId(entry.name)) continue;
    try {
      const bridge = targetPath(workspaceRoot, `${entry.name}/bridge.json`);
      if (!existsSync(bridge) || !statSync(bridge).isFile()) continue;
      const value = parseJsonText(readFileSync(bridge, 'utf8'));
      if (value.platform === entry.name && ['ai-platform-bridge/v1', 'ai-platform-bridge/v1.1'].includes(value.schema) && value.shared?.readOnly === true) discovered.push(entry.name);
    } catch { /* An invalid or escaping bridge is not a registered platform. */ }
  }
  return discovered.sort();
}

export function allPlatformIds(workspaceRoot) {
  const discovered = discoverPlatformIds(workspaceRoot);
  return [...PLATFORM_IDS, ...discovered.filter((id) => !PLATFORM_IDS.includes(id))];
}

import { existsSync, readFileSync, statSync } from 'node:fs';
import { sha256 } from './core/hash.mjs';
import { join, normalize, relative, resolve, sep } from 'node:path';

export const TOP_LEVEL_REQUIREMENTS = new Set(['versions/架构基本原则.md', 'AGENTS.md', 'AI_ARCHITECTURE_SYSTEM_PROMPT.md', 'agentic-workflow-master-manual.md', 'HANDOFF.md', 'invocation-adapters-spec.md']);
export const EXTRA_DOCUMENTS = [...TOP_LEVEL_REQUIREMENTS].filter((path) => !path.includes('/')).concat(['architecture-manager/README.md']);
export const UPDATE_LOG_PATH = 'versions/更新日志.md';

function normalizeRelativePath(relativePath) {
  if (typeof relativePath !== 'string' || relativePath.trim() === '') throw new Error('INVALID_DOCUMENT_PATH');
  const normalized = normalize(relativePath).split(sep).join('/');
  if (normalized.startsWith('../') || normalized === '..' || normalized.startsWith('/') || /^[A-Za-z]:\//.test(normalized)) {
    throw new Error('DOCUMENT_PATH_OUTSIDE_WORKSPACE');
  }
  if (!(normalized.startsWith('versions/') || normalized.startsWith('docs-site/docs/') || EXTRA_DOCUMENTS.includes(normalized)) || !normalized.endsWith('.md')) {
    throw new Error('DOCUMENT_PATH_NOT_ALLOWED');
  }
  return normalized;
}

export function documentKind(path) {
  if (path === UPDATE_LOG_PATH) return 'update-log';
  if (TOP_LEVEL_REQUIREMENTS.has(path)) return 'top-level-requirements';
  if (path.includes('实施表')) return 'implementation-table';
  if (path.includes('方案')) return 'proposal';
  if (path.includes('台账') || path.includes('LEDGER')) return 'ledger';
  return 'architecture-document';
}

export function readDocument(workspaceRoot, relativePath) {
  const safePath = normalizeRelativePath(relativePath);
  const absolutePath = resolve(workspaceRoot, safePath);
  const rootRelative = relative(resolve(workspaceRoot), absolutePath);
  if (rootRelative.startsWith(`..${sep}`) || rootRelative === '..' || !existsSync(absolutePath) || !statSync(absolutePath).isFile()) {
    throw new Error('DOCUMENT_NOT_FOUND');
  }
  const content = readFileSync(absolutePath, 'utf8');
  return {
    schema: 'architecture-manager-document/v1',
    path: safePath,
    kind: documentKind(safePath),
    sensitive: TOP_LEVEL_REQUIREMENTS.has(safePath),
    sha256: sha256(content),
    bytes: Buffer.byteLength(content, 'utf8'),
    content,
    writePerformed: false
  };
}

export function buildDocumentPlan({ workspaceRoot, relativePath, beforeText, afterText, baselineSha256, highSensitivityConfirmed = false, now = new Date().toISOString() }) {
  const safePath = normalizeRelativePath(relativePath);
  if (typeof beforeText !== 'string' || typeof afterText !== 'string') throw new Error('INVALID_DOCUMENT_CONTENT');
  const actualBeforeHash = sha256(beforeText);
  if (typeof baselineSha256 !== 'string' || baselineSha256 !== actualBeforeHash) throw new Error('DOCUMENT_BASELINE_MISMATCH');
  if (TOP_LEVEL_REQUIREMENTS.has(safePath) && highSensitivityConfirmed !== true) throw new Error('TOP_LEVEL_CONFIRMATION_REQUIRED');
  if (beforeText === afterText) throw new Error('NO_DOCUMENT_CHANGE');
  return {
    schema: 'architecture-manager-plan/v1',
    planId: `document-${now.replace(/[^0-9]/g, '').slice(0, 17)}`,
    kind: 'document-edit',
    workspaceRoot,
    generatedAt: now,
    applyMode: 'confirmation-required',
    writePerformed: false,
    target: { path: safePath, documentKind: documentKind(safePath), highSensitivity: TOP_LEVEL_REQUIREMENTS.has(safePath) },
    steps: [{
      operation: 'replace-document-content',
      target: safePath,
      oldSha256: actualBeforeHash,
      newSha256: sha256(afterText),
      oldBytes: Buffer.byteLength(beforeText, 'utf8'),
      newBytes: Buffer.byteLength(afterText, 'utf8'),
      checkpoint: true
    }],
