function createWindow() {
  const window = new BrowserWindow({
    width: 1360,
    height: 860,
    minWidth: 1024,
    minHeight: 680,
    show: false,
    webPreferences: {
      // Sandboxed Electron preload scripts must be CommonJS.  An ESM preload
      // is rejected by Electron before contextBridge can expose the API.
      preload: join(__dirname, 'preload.cjs'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true
    }
  });
  window.once('ready-to-show', () => {if(process.env.ARCHITECTURE_MANAGER_TEST_HIDDEN!=='1')window.show();});
  window.on('close', (event) => {
    if (!quitReady && lifecycle.pending) { event.preventDefault(); void safeQuit(); }
  });
  window.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
  window.loadFile(join(__dirname, '..', 'dist', 'index.html'));
  return window;
}

app.whenReady().then(() => {
  session.defaultSession.setPermissionRequestHandler((_webContents, _permission, callback) => callback(false));
  registerIpc();
  createWindow();
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});
app.on('before-quit', (event) => {
  if (!quitReady && lifecycle.pending) { event.preventDefault(); void safeQuit(); }
});

