        id:match[1],name:at('name') || match[2].trim(),duration:at('duration'),blocks:at('blocks'),artifacts:at('artifacts'),criteria:at('criteria'),status:at('status')
      });
    }
    if (steps.length > 0) documents.push({ path: `versions/${entry.name}`, steps });
  }
