    <button className="primary-small" disabled={working || !placement || !server} onClick={()=>act(async()=>{if(!await actionApi.confirm('确认连接这个 MCP 服务并读取工具清单？stdio 会启动所选程序；网络连接仅使用配置指定端点，不调用任何工具。'))return;const value=await actionApi.discoverNativeMcp({workspaceRoot:workspace,platformId,placementPlan:placement,server:server.configuration,runtimeExecutable:runtime,confirmed:true});setDiscovery(value);setPermissions({});setPage(0);setMessage(`已真实发现 ${value.tools.length} 个 MCP 工具；尚未执行工具功能。`);})}>2. 实际连接并读取工具</button>
