) }>3. 预览发布并绑定所选平台</button><p>将创建新冻结配方并切换所选平台到支持原生 MCP 的连接器。其它平台配置不变；未选工具不发布，工具实际调用仍须单独确认。</p></>}
    {error && <div className="scan-result warning" role="alert">{error}</div>}
  </section>;
}

import {useSelectionApi} from '../../shared/useSelectionApi.mjs';
import React,{useEffect,useRef,useState} from 'react';
import {friendlyError} from '../../presenter.mjs';
export function PlatformBodyForm({api,workspace,intake,inventory,setPlanPreview,setPlanPayload,setMessage}) {

  const [selection,setSelection]=useState('__new__'),[id,setId]=useState(''),[confirmed,setConfirmed]=useState(false),[fields,setFields]=useState({}),[displayName,setDisplayName]=useState(''),[mode,setMode]=useState('manual-native'),[args,setArgs]=useState('{client-descriptor}'),[identity,setIdentity]=useState('architecture-json-cli-client'),[error,setError]=useState(''),[working,setWorking]=useState(false),[result,setResult]=useState(null),[snapshot,setSnapshot]=useState(null);const serial=useRef(0),platformId=selection==='__new__'?id:selection;
  api=useSelectionApi(api,workspace+":"+platformId+":"+intake?.sourceFingerprint+":"+intake?.selectedEntry);
  useEffect(()=>{setWorking(false);const current=++serial.current;setSnapshot(null);setResult(null);if(!/^[a-z][a-z0-9-]{1,30}$/.test(platformId))return;api.readOnboardingConfig({workspaceRoot:workspace,platformId}).then(value=>{if(current!==serial.current)return;setFields(value.fields);setDisplayName(value.fields.displayName || platformId);setSnapshot(value);setError('');}).catch(error=>{if(current===serial.current)setError(friendlyError(error));});return ()=>{serial.current++;};},[api,workspace,platformId]);
  const act=async action=>{setWorking(true);setError('');try{const value=await action();if(value?.schema==='architecture-manager-plan/v1'){setPlanPreview(value);setPlanPayload(null);setMessage('平台本体接入计划已生成。配置和目录登记会明确保持待认证；安置不会启动客户端。');}else setResult(value);}catch(error){setError(friendlyError(error));}finally{setWorking(false);}};
  const pick=async key=>{try{const path=await api.selectOnboardingFile();if(path)setFields(previous=>({...previous,[key]:path}));else setError('已取消选择。');}catch(error){if(error.message!=='STALE_TASK_RESULT')setError(friendlyError(error));}};
  return <section className="panel"><div className="panel-title"><span>平台本体与原生入口</span><span className="muted">本体、桥接服务、原生客户端与能力地板分别验证</span></div>
    <div className="wizard-grid"><div className="wizard-field"><label>平台</label><select value={selection} onChange={event=>setSelection(event.target.value)}><option value="__new__">创建独立平台</option>{inventory?.platforms?.map(row=><option key={row.id} value={row.id}>{row.id}</option>)}</select></div>{selection==='__new__' && <div className="wizard-field"><label>新平台 ID</label><input value={id} onChange={event=>setId(event.target.value.toLowerCase())} placeholder="my-client" /></div>}<div className="wizard-field"><label>显示名称</label><input value={displayName} onChange={event=>setDisplayName(event.target.value)} /></div></div>
    {selection==='__new__' && <label><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} />允许创建这个一级平台目录，并登记到架构说明中。</label>}
    <div className="wizard-field"><label>准备架构服务的 Python 解释器</label><input value={fields.pythonExecutable || ''} onChange={event=>setFields(previous=>({...previous,pythonExecutable:event.target.value}))} /><div className="git-actions"><button className="small-button" onClick={()=>pick('pythonExecutable')}>选择解释器</button><button className="small-button" disabled={working || !fields.pythonExecutable} onClick={()=>act(async()=>{const value=await api.detectOnboardingRuntime({pythonExecutable:fields.pythonExecutable});if(value.python?.executable)setFields(previous=>({...previous,pythonExecutable:value.python.executable}));return value;})}>检测所选解释器与 WSL</button></div></div>
    {snapshot?.performanceRecommendation && <button className="small-button" onClick={()=>setFields(previous=>({...previous,...snapshot.performanceRecommendation}))}>选择已发布的提速组合</button>}
    <div className="wizard-field"><label>本体提供什么接口</label><select value={mode} onChange={event=>setMode(event.target.value)}><option value="manual-native">GUI／接口未明确：安置本体，原生接线保持待完成</option><option value="json-cli">已实现架构 JSON stdin/stdout 协议的 CLI 客户端</option></select></div>
    {mode==='json-cli' && <details open><summary>明确的客户端启动配置</summary><p>客户端必须经架构服务返回随机挑战回执。普通软件的“--version”或仅能启动窗口不能代替此接口。</p><div className="wizard-field"><label>入口参数（每行一项，按原样传递）</label><textarea rows={4} value={args} onChange={event=>setArgs(event.target.value)} /><small>可使用 {'{client-body}'}、{'{client-descriptor}'}、{'{mcp-registration}'}、{'{runner-config}'}；预览会显示实际路径。</small></div><div className="wizard-field"><label>客户端回执身份</label><input value={identity} onChange={event=>setIdentity(event.target.value)} /></div><div className="wizard-field"><label>非 Python 脚本需要的 Node／Java 等程序（可留空）</label><input value={fields.clientRuntimeExecutable || ''} onChange={event=>setFields(previous=>({...previous,clientRuntimeExecutable:event.target.value}))} /><button className="small-button" onClick={()=>pick('clientRuntimeExecutable')}>选择运行程序</button></div></details>}
    <div className="git-actions"><button className="primary-small" disabled={working || !snapshot || !fields.pythonExecutable || selection==='__new__' && !confirmed} onClick={()=>act(()=>api.previewPlatformBody({intake,platformId,displayName,fields,confirmed,clientMode:mode,clientArgs:mode==='json-cli'?args.split(/\r?\n/).filter(Boolean):[],clientIdentity:identity}))}>预览本体接入</button><button className="small-button" disabled={working || !platformId} onClick={()=>act(()=>api.probeOnboardingClient({workspaceRoot:workspace,platformId}))}>测试已接入的真实客户端</button></div>
    {error && <div className="scan-result warning" role="alert">{error}</div>}
    {result && <div className={'scan-result '+(result.status==='passed'?'clean':'warning')}>{result.importedClientVerified?'所选本体的真实 CLI 连接已通过；还需能力地板和首次认证。':result.status==='passed'?'架构服务回环已通过；未据此声称厂商客户端已接线。':result.issues?.join('；') || result.status}<div className="path-line">{result.evidencePath || ''}</div></div>}
    <p>本体安置后，请到「平台与接入」选择这个平台，准备独立环境并运行接入／继续。缺原生接口、系统组件或登录时保持明确待完成状态；管理台不会要求 AI 会话手改配置，也不会据此刷绿。</p>
  </section>;
}

import {useSelectionApi} from '../../shared/useSelectionApi.mjs';
import React,{useEffect,useState,useRef} from 'react';
import {friendlyError} from '../../presenter.mjs';
const newAction=()=>({name:'',args:'',parameters:[],sideEffects:'none',filesystem:'read',network:'none',probeReadOnly:false});
export function SoftwareBodyForm({api,workspace,platformId,intake,setMessage,setPlanPreview,setPlanPayload}) {

  const [id,setId]=useState(''),[displayName,setDisplayName]=useState(''),[upstream,setUpstream]=useState(''),[version,setVersion]=useState(''),[mode,setMode]=useState('cli'),[runtime,setRuntime]=useState(''),[versionArgs,setVersionArgs]=useState('--version'),[launchArgs,setLaunchArgs]=useState(''),[actions,setActions]=useState([]),[placement,setPlacement]=useState(null),[working,setWorking]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null);
  const identity=workspace+":"+platformId+":"+intake.sourceFingerprint+":"+intake.selectedEntry+":"+id,current=useRef(identity);current.current=identity;
  api=useSelectionApi(api,identity);
  const modeTouched=useRef(false);
  useEffect(()=>{let active=true;api.suggestBodyImport({workspaceRoot:workspace,platformId,intake}).then(value=>{if(!active)return;setId(previous=>previous || value.fields.resourceId);setDisplayName(previous=>previous || value.fields.displayName);setVersion(previous=>previous || value.fields.version);if(value.mode && !modeTouched.current)setMode(value.mode);}).catch(error=>{if(active && error.message!=='STALE_TASK_RESULT')setError(friendlyError(error));});return ()=>{active=false;};},[workspace,platformId,intake]);
  useEffect(()=>{setWorking(false);setResult(null);},[identity]);
  useEffect(()=>{let active=true;setPlacement(null);if(platformId && id)api.listRuntimeBodies({workspaceRoot:workspace,platformId}).then(rows=>{if(active){const previous=rows.findLast(row=>row.plan.target.resourceId===id && row.plan.payload.intake.sourceFingerprint===intake.sourceFingerprint && row.plan.payload.intake.selectedEntry===intake.selectedEntry);if(previous)setPlacement(previous.plan);}}).catch(error=>{if(active)setError(friendlyError(error));});return ()=>{active=false;};},[api,workspace,platformId,id,intake.sourceFingerprint,intake.selectedEntry]);
  const plan=async action=>{const selected=identity;setWorking(true);setError('');try{const value=await action();if(!value)return;setPlanPreview(value);setPlanPayload(null);setMessage('请核对软件计划并确认执行。版本询问、功能测试和会话状态各自记录。');}catch(error){if(selected===current.current && error.message!=='STALE_TASK_RESULT')setError(friendlyError(error));}finally{if(selected===current.current)setWorking(false);}};
  const update=(index,patch)=>setActions(rows=>rows.map((row,i)=>i===index?{...row,...patch}:row));
  const serialize=()=>actions.map(row=>({...row,args:row.args.split(/\r?\n/).filter(Boolean),testArguments:Object.fromEntries(row.parameters.filter(parameter=>parameter.testValue!=='').map(parameter=>[parameter.name,parameter.type==='integer'?Number(parameter.testValue):parameter.type==='boolean'?parameter.testValue==='true':parameter.testValue]))}));
  const relay=operation=>plan(()=>api.previewSoftwareCommand({workspaceRoot:workspace,platformId,softwareId:id,operation}));
  return <section className="panel"><div className="panel-title"><span>软件本体、功能与会话</span><span className="muted">安置 → 声明并测试 → 发布和绑定</span></div>
    <div className="wizard-grid"><div className="wizard-field"><label>软件 ID（更新使用同一个 ID）</label><input value={id} onChange={event=>{setId(event.target.value.toLowerCase());setPlacement(null);}} placeholder="my-software" /></div><div className="wizard-field"><label>显示名称</label><input value={displayName} onChange={event=>setDisplayName(event.target.value)} /></div><div className="wizard-field"><label>本体版本（CLI 查询必须包含此值）</label><input value={upstream} onChange={event=>setUpstream(event.target.value)} /></div><div className="wizard-field"><label>配方版本（留空自动递增）</label><input value={version} onChange={event=>setVersion(event.target.value)} placeholder="1.0.0" /></div></div>
    <p>普通 CLI 与 GUI 会话使用通用连接器，不必逐个编写 MCP。安装包仅安置，完成安装后重新选择实际本体。原件保留；备份与恢复副本共两份完整数据。请选完整安装目录；单独的 EXE 若依赖旁边的库，不能脱离它们运行。</p><p>确认配方计划会采用新共享默认版并绑定所选平台；其它平台的本体未更新时会明确报不匹配。在途 run 保留原锁。撤销导入可恢复旧指针和绑定，两个冻结版本与备份保留。</p>
    <button className="primary-small" disabled={working || !platformId || !id} onClick={()=>plan(async()=>{const value=placement || await api.previewSoftwareBodyPlacement({workspaceRoot:workspace,intake,platformId,softwareId:id});setPlacement(value);return value;})}>1. 预览安置／继续与恢复</button>
    {placement && <><div className="path-line">拟安置：{placement.target.path}<br />程序入口：{placement.target.path+'\\'+placement.target.entry}<br />备份：{placement.target.backup}</div><button className="small-button" disabled={working} onClick={async()=>{setError('');try{const value=await api.verifyPlan({plan:placement});setResult(value);if(!value.ok)setError('本体尚未安置或回读未通过，请先确认执行安置计划。');}catch(error){setError(friendlyError(error));}}}>读取实际安置结果</button><p>安置只是保存程序文件，尚未建立调用绑定。已有配方请选择下面的绑定；新软件使用第 2 步创建配方。</p><button className="primary-small" disabled={working} onClick={()=>plan(()=>api.previewExistingSoftwareBinding({placementPlan:placement}))}>绑定到现行配方（不发布新版本）</button></>}
    <div className="wizard-field"><label>软件形式</label><select value={mode} onChange={event=>{modeTouched.current=true;setMode(event.target.value);}}><option value="cli">CLI／脚本：映射具体动作</option><option value="gui">GUI：启动、检查存活、关闭本次会话</option></select></div>
    {mode==='cli'?<><div className="wizard-field"><label>脚本解释器（EXE 可留空；Python 可使用本平台解释器）</label><input value={runtime} onChange={event=>setRuntime(event.target.value)} /><button className="small-button" disabled={working} onClick={()=>plan(async()=>{const path=await api.selectOnboardingFile();if(path)setRuntime(path);else setError('已取消选择。');return null;})}>选择运行程序</button></div><div className="wizard-field"><label>版本查询参数（每行一项）</label><textarea rows={2} value={versionArgs} onChange={event=>setVersionArgs(event.target.value)} /></div>
      {actions.map((action,index)=><fieldset key={index}><legend>功能 {index+1}</legend><div className="wizard-grid"><label>动作名称<input value={action.name} onChange={event=>update(index,{name:event.target.value})} /></label><label>固定参数（每行一项）<textarea value={action.args} onChange={event=>update(index,{args:event.target.value})} /></label><label>影响<select value={action.sideEffects} onChange={event=>update(index,{sideEffects:event.target.value,probeReadOnly:false})}><option value="none">只读</option><option value="local-write">本机写入</option><option value="external">外部操作</option></select></label><label>文件范围<select value={action.filesystem} onChange={event=>update(index,{filesystem:event.target.value})}><option value="none">无</option><option value="read">读取</option><option value="workspace">项目工作区</option></select></label><label>网络范围<select value={action.network} onChange={event=>update(index,{network:event.target.value,probeReadOnly:false})}><option value="none">无</option><option value="loopback">本机回环</option><option value="public">公开网络（每次确认）</option></select></label></div>
        {action.parameters.map((parameter,p)=><div className="wizard-grid" key={p}><label>参数名<input value={parameter.name} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,name:event.target.value}:row)})} /></label><label>命令标记<input value={parameter.flag} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,flag:event.target.value}:row)})} placeholder="--input" /></label><label>类型<select value={parameter.type} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,type:event.target.value}:row)})}><option value="string">文字</option><option value="integer">整数</option><option value="boolean">true / false</option></select></label><label>排列<select value={parameter.style} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,style:event.target.value}:row)})}><option value="repeat">标记 空格 值</option><option value="equals">标记=值</option><option value="positional">只传值</option></select></label><label>只读测试值<input value={parameter.testValue} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,testValue:event.target.value}:row)})} /></label><label><input type="checkbox" checked={parameter.required} onChange={event=>update(index,{parameters:action.parameters.map((row,i)=>i===p?{...row,required:event.target.checked}:row)})} />必填</label><button className="small-button" onClick={()=>update(index,{parameters:action.parameters.filter((_,i)=>i!==p)})}>移除参数</button></div>)}
        <div className="git-actions"><button className="small-button" onClick={()=>update(index,{parameters:[...action.parameters,{name:'',flag:'',type:'string',style:'repeat',required:false,testValue:''}]})}>添加参数</button><button className="small-button" onClick={()=>setActions(rows=>rows.filter((_,i)=>i!==index))}>移除动作</button><label><input type="checkbox" disabled={action.sideEffects!=='none' || action.network!=='none' || action.filesystem==='workspace'} checked={action.probeReadOnly} onChange={event=>update(index,{probeReadOnly:event.target.checked})} />我确认现在执行这条只读功能测试</label></div></fieldset>)}<button className="small-button" onClick={()=>setActions(rows=>[...rows,newAction()])}>添加功能动作</button></>:<div className="wizard-field"><label>启动参数（每行一项，可留空）</label><textarea value={launchArgs} onChange={event=>setLaunchArgs(event.target.value)} /><p>GUI 内部操作仍由你完成。会话启动不等于程序功能已自动化或已验证。</p></div>}
    <div className="git-actions"><button className="primary-small" disabled={working || !placement || !displayName || mode==='cli' && !upstream} onClick={()=>plan(()=>api.previewSoftwareBody({workspaceRoot:workspace,platformId,placementPlan:placement,displayName,upstreamVersion:upstream || 'unknown',releaseVersion:version || null,mode,runtimeExecutable:runtime,versionArgs:versionArgs.split(/\r?\n/).filter(Boolean),actions:serialize(),launchArgs:launchArgs.split(/\r?\n/).filter(Boolean)}))}>{mode==='cli'?'2. 只读询问并预览配方与绑定':'2. 预览 GUI 会话配方与绑定'}</button><button className="small-button" disabled={working || !id} onClick={()=>relay('call')}>预览查询现行版本</button>{['open','status','close'].map(operation=><button className="small-button" disabled={working || !id} key={operation} onClick={()=>relay(operation)}>{({open:'预览启动本次会话',status:'预览检查会话存活',close:'预览关闭本次会话'})[operation]}</button>)}</div>
    {error && <div className="scan-result warning" role="alert">{error}</div>}{result && <div className={'scan-result '+(result.ok?'clean':'warning')}>{result.ok?'安置和真实恢复已通过；请继续绑定到现行配方或完成第 2 步。':'尚未通过安置回读。'}<div className="path-line">{result.entry || result.target}</div></div>}
  </section>;
}

import {useSelectionApi} from '../../shared/useSelectionApi.mjs';
import React,{useEffect,useRef,useState} from 'react';
import {friendlyError} from '../../presenter.mjs';
export function ToolBodyForm({api,workspace,platformId,intake=null,resource=null,setPlanPreview,setPlanPayload,setMessage,onClose=null}) {
  api=useSelectionApi(api,workspace+":"+platformId+":"+(intake?.sourceFingerprint || resource?.resourceId || "")+":"+(intake?.selectedEntry || resource?.version || ""));
  const [editor,setEditor]=useState(null),[fields,setFields]=useState({resourceId:'',version:'1.0.0',displayName:'',dependencies:{workflows:{},skills:{},packs:{}}}),[body,setBody]=useState(''),[stages,setStages]=useState([]),[editStages,setEditStages]=useState(false),[error,setError]=useState(''),[working,setWorking]=useState(false),[options,setOptions]=useState(null),[filter,setFilter]=useState('');const serial=useRef(0);
  useEffect(()=>{const current=++serial.current;setEditor(null);setError('');Promise.all([api.readToolBodyEditor({workspaceRoot:workspace,platformId,intake,...resource}),api.listBodyDependencies({workspaceRoot:workspace})]).then(([value,choices])=>{if(current!==serial.current)return;setEditor(value);setFields(value.fields);setBody(value.definition?'':value.content);setOptions(choices);setEditStages(!value.definition);setStages(value.definition?.stages?.map(row=>({...row,body:value.stageBodies?.[row.id]})) || (value.intake && /\.(py|js|mjs|ps1|sh)$/i.test(value.intake.selectedEntry)?[{id:'RUN',action:'script',worker:'expert',script:'original/'+value.intake.selectedEntry,arguments:{argv:[],timeoutSeconds:30}}]:[{id:'INTAKE',action:'prompt',worker:'expert',body:value.content}]));}).catch(error=>{if(current===serial.current)setError(friendlyError(error));});return ()=>{serial.current++;};},[api,workspace,platformId,intake,resource]);
  const update=(key,value)=>setFields(previous=>({...previous,[key]:value}));
  const stage=(index,key,value)=>setStages(previous=>previous.map((row,position)=>position===index?{...row,[key]:value}:row));
  const preview=async()=>{setWorking(true);setError('');try{const plan=await api.previewToolBody({workspaceRoot:workspace,platformId,intake:editor.intake,...fields,content:editStages?body:undefined,stages:editStages?stages:null,manifest:editor.manifest,definition:editor.definition,adopt:true});setPlanPreview(plan);setPlanPayload(null);setMessage('工作流接入计划已生成，尚未执行脚本或正文任务。');}catch(error){setError(friendlyError(error));}finally{setWorking(false);}};
  return <section className="panel"><div className="panel-title"><span>{resource?'编辑工作流并发布更新':'工作流正文与阶段设置'}</span>{onClose && <button className="small-button" onClick={onClose}>关闭编辑</button>}</div>{error && <div className="scan-result warning" role="alert">{error}</div>}
    {!editor?<p>正在读取来源与已有定义…</p>:<>
      <div className="wizard-grid"><div className="wizard-field"><label>资源 ID</label><input value={fields.resourceId} readOnly={fields.updating} onChange={event=>update('resourceId',event.target.value)} placeholder="my-workflow" /></div><div className="wizard-field"><label>显示名称</label><input value={fields.displayName} onChange={event=>update('displayName',event.target.value)} /></div><div className="wizard-field"><label>新版本</label><input value={fields.version} onChange={event=>update('version',event.target.value)} /></div></div>
      {editor.definition && <><label><input type="checkbox" checked={editStages} onChange={event=>setEditStages(event.target.checked)} />修改阶段（未勾选时保留原定义和所有支持文件，只更新身份）</label><details><summary>查看完整原定义</summary><pre>{JSON.stringify(editor.definition,null,2)}</pre></details></>}
      {editStages && <><p>按顺序填写阶段。提示词由客户端处理；脚本只有在用户明确启动业务、并满足平台隔离条件时才执行。</p><div className="wizard-field"><label>任务说明</label><textarea rows={7} value={body} onChange={event=>setBody(event.target.value)} /></div>
        {stages.map((row,index)=><div className="notice" key={index}><div className="wizard-grid"><div className="wizard-field"><label>阶段 ID</label><input value={row.id} onChange={event=>stage(index,'id',event.target.value)} /></div><div className="wizard-field"><label>动作</label><select value={row.action} onChange={event=>stage(index,'action',event.target.value)}><option value="prompt">提示词</option><option value="script">原始脚本</option>{!['prompt','script'].includes(row.action) && <option value={row.action}>保留原动作：{row.action}</option>}</select></div>
          {row.action==='script' && <div className="wizard-field"><label>脚本入口</label><select value={row.script || ''} onChange={event=>stage(index,'script',event.target.value)}><option value="">请选择脚本</option>{editor.intake?.files.filter(file=>file.included && /\.(py|js|mjs|ps1|sh)$/i.test(file.path)).map(file=><option key={file.path} value={'original/'+file.path}>{file.path}</option>)}</select><small>EXE／DLL 等程序本体请按软件接入。</small></div>}
        </div>{row.action==='prompt' && <div className="wizard-field"><label>本阶段说明（留空使用上方任务说明）</label><textarea rows={4} value={row.body || ''} onChange={event=>stage(index,'body',event.target.value)} /></div>}{row.action==='script' && <><div className="wizard-field"><label>脚本参数（每行一个原样参数）</label><textarea rows={3} value={(row.arguments?.argv || []).join('\n')} onChange={event=>stage(index,'arguments',{...row.arguments,argv:event.target.value.split(/\r?\n/).filter(line=>line.length)})} /></div><div className="wizard-field"><label>超时秒数</label><input type="number" min="1" max="3600" value={row.arguments?.timeoutSeconds || 30} onChange={event=>stage(index,'arguments',{...row.arguments,timeoutSeconds:Number(event.target.value)})} /></div></>}
          <button className="small-button" disabled={stages.length===1} onClick={()=>setStages(previous=>previous.filter((_,position)=>position!==index))}>移除此阶段</button></div>)}<button className="small-button" onClick={()=>setStages(previous=>[...previous,{id:'STEP_'+(previous.length+1),action:'prompt',worker:'expert'}])}>添加阶段</button>
      </>}
      <details><summary>精确技能依赖</summary><input value={filter} onChange={event=>setFilter(event.target.value)} placeholder="筛选技能（显示前 50 条）" />{options.skills.filter(row=>!filter || row.id.includes(filter)).slice(0,50).map(row=><label className="dependency-choice" key={row.id}><input type="checkbox" checked={Boolean(fields.dependencies.skills?.[row.id])} onChange={event=>{const pins={...fields.dependencies.skills};if(event.target.checked)pins[row.id]=row.version;else delete pins[row.id];update('dependencies',{...fields.dependencies,skills:pins});}} />{row.id}@{row.version}</label>)}<p>已选：{Object.entries(fields.dependencies.skills || {}).map(([id,pin])=>id+'@'+pin).join('、') || '无'}</p></details>
      <div className="git-actions"><button className="primary-small" disabled={working || !platformId || !fields.resourceId || editStages && !stages.length} onClick={preview}>{working?'检查定义与依赖…':'预览接入／更新'}</button></div>
    </>}
  </section>;
}

// Domain commands take a captured workspace context; late results are guarded centrally.
export function createCommands() {
  return {
    executePlan:async (context)=> {
      const {workspace,setInventory,setBusy,message,setMessage,api,planPreview,setPlanPreview,planPayload,setPlanPayload,setTransactionProgress,setGitDetails,setTargetVersions,integrationTargetId,integrationPath,setIntegrationTargetVersion,software,reloadIntegrationTarget,inspectAnchor,friendlyError,PLAN_WRITE_KINDS}=context;

    if (!planPreview) return;
    if (planPreview.kind === 'software-action' && planPreview.target?.mode === 'open-location') {
      if (!await api.confirm(`确认打开软件目录？\n\n${planPreview.target.bodyPath}`)) return;
      try {
        await api.openSoftwareLocation({ workspaceRoot: workspace, softwareId: planPreview.target.softwareId, platformId: planPreview.target.platformId, expectedPath: planPreview.target.bodyPath });
        setPlanPreview(null);
        setMessage('已打开软件本体目录。');
      } catch (error) {
        setMessage(`软件目录打开失败：${friendlyError(error)}`);
      }
      return;
    }
    if (!PLAN_WRITE_KINDS.includes(planPreview.kind)) return;
    const target = planPreview.target?.path || (planPreview.target?.platformIds ? `所有已接入平台：${planPreview.target.platformIds.join('、')}` : planPreview.target?.platformId ? `平台：${planPreview.target.platformId}` : `${planPreview.target?.repository}/${planPreview.target?.resourceId}/current.json`);
    if (!await api.confirm(`确认执行此计划？\n\n目标：${target}\n\n执行前会再次核对文件状态，失败会阻止覆盖。`)) return;
    setBusy(true);
    setTransactionProgress(null);
    try {
      const applied = await api.applyPlan({ plan: planPreview, afterText: planPayload?.afterText, credentialValue:planPayload?.credentialValue, actor: 'local-user' });
      if(planPreview.kind==='mcp-credential')setPlanPayload(null);
      if(applied.stoppedAfterCompletion && planPreview.kind!=='platform-global-update') {
        setMessage('停止请求到达时当前原子步骤已完成；结果已保留，后续验证尚未运行。请重新扫描并查看审计记录。');
        setPlanPreview(null);setPlanPayload(null);return;
      }
      if (planPreview.kind === 'platform-onboarding' && !['complete','configured-pending'].includes(applied.status)) {
        setMessage(`接入已停止在 ${applied.stoppedAt || applied.currentStep || '未完成步骤'}：${friendlyError(new Error(applied.error || '检查未通过'))}。修正后可点击“预览一键接入／继续”，已通过步骤保留。`);
        return;
      }
      const verification = await api.verifyPlan({ plan: planPreview });
      if(planPreview.kind==='platform-global-update') {
        window.dispatchEvent(new window.CustomEvent('global-update-result',{detail:{workspaceRoot:workspace,plan:planPreview,result:applied}}));
        const complete=(applied.results || []).filter(row=>['complete','no-change'].includes(row.status)).length;
        setMessage(`本次所有平台更新结果：${complete} 个完成，${(applied.results || []).length-complete} 个待补或已停止，${(applied.skipped || []).length} 个跳过。各平台结果和继续入口见更新面板。`);
        setInventory(await api.scanWorkspace(workspace));setPlanPreview(null);setPlanPayload(null);return;
      }
      if(planPreview.kind==='platform-global-update-restore'){const history=await api.readGlobalUpdateHistory({workspaceRoot:workspace});if(history)window.dispatchEvent(new window.CustomEvent('global-update-result',{detail:{workspaceRoot:workspace,plan:history.plan,result:history.result}}));setInventory(await api.scanWorkspace(workspace));setMessage(verification.ok?'本次旧接入配置已恢复。新环境和证据保留。':'恢复未通过，请查看外部变化和审计记录。');setPlanPreview(null);setPlanPayload(null);return;}

      const refreshed = await api.scanWorkspace(workspace);
      setInventory(refreshed);
      if (refreshed.git) setGitDetails(refreshed.git);
      if (integrationTargetId && integrationPath) await reloadIntegrationTarget();
      setIntegrationTargetVersion('');
      setTargetVersions({});
      setPlanPreview(null);
      setPlanPayload(null);
      if(planPreview.kind==='platform-onboarding' && applied.status==='configured-pending'){setMessage(`本轮配置已保存，架构接入尚未完成。暂缓/待补步骤 ${(applied.pending || []).length} 项，未绑定软件 ${(applied.pendingSoftware || []).length} 项；取消暂缓勾选或补齐后可继续。`);return;}
      if(planPreview.kind==='platform-body') {setMessage(verification.ok?'平台本体安置和真实恢复已通过；'+(applied.nativeStatus==='interface-required'?'原生接口仍待补齐。':'客户端需点击真实入口测试。')+'能力地板、首次认证和入库通过后才算架构接入完成。':'本体回读未通过，请查看接入记录。');return;}
      // Aligning a platform is not the end of the operation: the platform must re-certify itself
      // against the configuration it now has, and that run is what produces the readable evidence.
      if(planPreview.kind==='platform-anchor-alignment') {
        const targetId=planPreview.target.platformId;
        if(!verification.ok){setMessage(`${targetId} 的配置已写入，但回读未通过：${(verification.differences || []).map(difference=>`${difference.key} ${difference.current}→${difference.expected}`).join('；') || '见审计记录'}。请先处理差异再认证。`);return;}
        setMessage(`${targetId} 已对齐到锚定代，正在用该平台自己的配置补跑受影响格与能力地板检查。`);
        setTransactionProgress({phase:`${targetId} 对齐后认证`,state:'running'});
        try {
          const certified=await api.checkAfterAnchorAlignment({ workspaceRoot: workspace, platformId: targetId, anchorDigestSha256: planPreview.target.anchorDigest });
          const counts=certified.firstCertification?.counts || certified.steps?.find(step=>step.step==='post-alignment-check')?.result?.counts || null;
          if(certified.status==='failed'||certified.status==='cancelled'){setMessage(`${targetId} 对齐完成，但认证停在 ${certified.stoppedAt || '检查步骤'}：${friendlyError(new Error(certified.error || '检查未通过'))}。配置已生效；修正后可再点“检查受影响调用”。`);}
          else if(certified.firstCertification){setMessage(`${targetId} 对齐并完成首次认证：矩阵 ${counts?.pass ?? '?'} 通过 / ${counts?.fail ?? '?'} 失败，证据哈希已固化。`);}
          else {setMessage(`${targetId} 对齐完成；本轮检查未产生可固化的首次认证（记录状态 ${certified.status}），证据路径见接入记录。`);}
        } catch (error) {
          setMessage(`${targetId} 配置已对齐，但自动认证未能执行：${friendlyError(error)}。可在“平台与接入”里手动点击“检查受影响调用”。`);
        } finally { setTransactionProgress(null); }
        try { await inspectAnchor(); } catch { /* the alignment itself already succeeded */ }
        return;
      }
      if(planPreview.kind==='software-command') {setMessage(applied.reply?.ok?'连接器已返回真实结果：'+(applied.reply.state || planPreview.target.capability)+'；这是本次调用／存活读数。':(applied.reply?.error?.named?.nativeCallMayHaveRun?'功能可能已经执行，返回结果未能确认；请先核实，勿重复提交：':'连接器未完成本次操作：')+friendlyError(applied.reply?.error?.code || 'SOFTWARE_CONNECTOR_FAILED'));return;}
setMessage(planPreview.kind === 'software-launch' ? `连接器答复：${applied.connectorStatus}。${applied.connectorReply?.error?.message || ''}启动只在连接器明确返回存活会话时成立。` : planPreview.kind === 'software-import' ? `软件本体安置与恢复演练${verification.ok ? '通过' : '未通过'}；尚未发布配方，也未接入连接器。` : planPreview.kind === 'software-recipe-publish' ? applied.status === 'published-version-only' && verification.ok ? `版本查询已发布，连接器健康检查和单格认证均通过；其它功能尚需适配。` : `配方文件${verification.ok ? '已发布' : '回读失败'}，但软件仍待验证：${applied.check?.issues?.join('；') || '缺少健康检查结果'}。` : planPreview.kind === 'software-revert' ? `软件撤销/停用${verification.ok ? '已验证' : '验证未通过'}；${applied.releaseRetained ? '已发布版本按只读规则保留。' : '备份保留，本体已移入垃圾桶。'}` : `计划已${applied.status === 'already-applied' ? '确认已执行' : '执行'}，验证${verification.ok ? '通过' : '未通过'}。`);
    } catch (error) {
      setMessage(`计划执行失败：${friendlyError(error)}`);
    } finally {
      setBusy(false);
      setTransactionProgress(null);
    }
  
    },
  };
}

import React,{useEffect,useState} from 'react';
import {SchemaFields} from '../../shared/SchemaFields.jsx';
import {convertFields} from '../../shared/schema-fields.mjs';
import {friendlyError} from '../../presenter.mjs';
export function SoftwareActionsPanel({api,workspace,platformId,softwareId,setPlanPreview,setPlanPayload,setMessage}) {
  const [details,setDetails]=useState(null),[selected,setSelected]=useState(''),[values,setValues]=useState({}),[error,setError]=useState(''),[references,setReferences]=useState('');
  useEffect(()=>{let active=true;setDetails(null);setError('');if(softwareId)api.readSoftwareBodyActions({workspaceRoot:workspace,softwareId,platformId}).then(value=>{if(active){setDetails(value);setSelected(value.actions[0]?.name || '');setValues({});setReferences((value.requiredReferences || []).join('\n'));}}).catch(error=>{if(active)setError(friendlyError(error));});return ()=>{active=false;};},[api,workspace,platformId,softwareId]);
  const action=details?.actions.find(row=>row.name===selected);
  const preview=async operation=>{setError('');try{const arguments_=convertFields(action?.inputSchema || {type:'object'},values) || {};const plan=await api.previewSoftwareCommand({workspaceRoot:workspace,platformId,softwareId,operation,capability:selected,arguments:arguments_,credentialReferences:references.split(/\r?\n/).filter(Boolean)});setPlanPreview(plan);setPlanPayload(null);setMessage('软件动作计划已生成；确认后经所选平台的连接器调用。');}catch(error){setError(friendlyError(error));}};
  if(!softwareId)return null;
  return <section className="panel"><div className="panel-title"><span>{softwareId}：功能与本次会话</span><span className="muted">{details?.version || ''}</span></div><p>所属平台：{platformId || '请先选择平台'}。启动、存活与具体功能测试分别记录；关闭只针对管理台本次登记的会话。</p>
    {details && <><select value={selected} onChange={event=>{setSelected(event.target.value);setValues({});}}>{details.actions.map(row=><option key={row.name} value={row.name}>{row.nativeName || row.name} · {row.observed?'有冻结证据':'待验证'}</option>)}</select>
      {action && <SchemaFields key={selected} schema={action.inputSchema} value={values} onChange={setValues} />}
      <label className="wizard-field">凭据引用（每行一个 reference:名称；不填写密码）<textarea rows={2} value={references} onChange={event=>setReferences(event.target.value)} /></label>
      <div className="git-actions"><button className="primary-small" disabled={!platformId || !selected || action?.observed===false} onClick={()=>preview('call')}>预览调用这个功能</button>{['open','status','close'].map(operation=><button className="small-button" key={operation} disabled={!platformId} onClick={()=>preview(operation)}>{({open:'预览启动',status:'预览检查存活',close:'预览关闭'})[operation]}</button>)}</div></>}
    {error && <div className="scan-result warning" role="alert">{error}</div>}
  </section>;
}

// Domain commands take a captured workspace context; late results are guarded centrally.
export function createCommands() {
  return {
    checkSoftware:async (context, item, platformId)=> {
      const {workspace,setBusy,setMessage,api,setTransactionProgress,setSoftwareResults,friendlyError}=context;

    setBusy(true);
    try {
      const result = await api.softwareHealth({ workspaceRoot: workspace, softwareId: item.id,platformId });
      setSoftwareResults((state) => ({ ...state, [platformId+'/'+item.id]: result }));
      setMessage(`${platformId}/${item.id} 健康检查：${result.description || result.status}`);
    } catch (error) {
      setMessage(`软件健康检查失败：${friendlyError(error)}`);
    } finally {setBusy(false);setTransactionProgress(null);}

    },
    previewSoftware:async (context, item)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,friendlyError}=context;

    try {
      const plan = await api.previewSoftwarePlan({ workspaceRoot: workspace, softwareId: item.id, mode: 'launch' });
      setPlanPreview(plan);
      setPlanPayload(null);
      setMessage(`已列出 ${item.id} 的启动条件。当前管理台没有启动执行器，未启动软件。`);
    } catch (error) {
      setMessage(`软件启动计划被拒绝：${friendlyError(error)}`);
    }

    },
    previewSoftwareImport:async (context, selection)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,friendlyError}=context;

    try {
      const plan = await api.previewSoftwareImportPlan({ workspaceRoot: workspace, ...selection });
      setPlanPreview(plan); setPlanPayload(null);
      setMessage(`已生成 ${selection.softwareId} 安置与备份计划：${plan.rows.length} 个文件，预计新增 ${Math.ceil((plan.estimatedAdditionalBytes || 0) / 1024 / 1024)} MiB（备份 + 本体，不含原下载文件）；尚未复制。`);
    } catch (error) { setMessage(`软件安置计划被拒绝：${friendlyError(error)}`); }

    },
    previewSoftwareRecipe:async (context, selection)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,friendlyError}=context;

    if (!await api.confirm(`确认只读询问 ${selection.softwareId} 的版本？\n\n管理台会启动你选定的程序并传入 ${selection.versionFlag}；程序本身仍可能有副作用。请仅对可信软件继续。`)) return;
    try {
      const plan = await api.previewSoftwareRecipePlan({ workspaceRoot: workspace, ...selection });
      setPlanPreview(plan); setPlanPayload(null);
      setMessage(`已从真实程序取得版本输出并生成配方计划；尚未发布，且只声明“版本查询”能力。`);
    } catch (error) { setMessage(`配方计划被拒绝：${friendlyError(error)}`); }

    },
    previewSoftwareLocation:async (context, item, platformId)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,friendlyError}=context;

    try {
      const plan = await api.previewSoftwarePlan({ workspaceRoot: workspace, softwareId: item.id, platformId, mode: 'open-location' });
      setPlanPreview(plan);
      setPlanPayload(null);
      setMessage(`已生成打开 ${item.id} 本体目录的计划，确认后才会打开资源管理器。`);
    } catch (error) {
      setMessage(`软件位置计划被拒绝：${friendlyError(error)}`);
    }

    },
    previewSoftwareConnectorLaunch:async (context, item, platformId)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,friendlyError}=context;

    if (!workspace || !platformId) return;
    try {
      const plan = await api.previewSoftwareConnectorLaunchPlan({ workspaceRoot: workspace, platformId, softwareId: item.id });
      setPlanPreview(plan);
      setPlanPayload(null);
      setMessage(`已生成 ${item.id} 经 ${platformId} 连接器的启动计划；连接器的答复会原样转达（含 INTERACTIVE_REQUIRED / 漂移），不会美化。`);
    } catch (error) {
      setMessage(`启动计划被拒绝：${friendlyError(error)}`);
    }

    },
    previewSoftwareRevert:async (context, item)=> {
      const {workspace,setMessage,api,setPlanPreview,setPlanPayload,software,friendlyError}=context;

    try {
      const plan = await api.previewSoftwareRevertPlan({ workspaceRoot: workspace, checkpointPath: item.checkpointPath });
      setPlanPreview(plan); setPlanPayload(null);
      setMessage(item.action === 'software-import' ? '已生成撤销安置计划：本体将移入 inbox/trash，备份保留。' : '已生成停用发布计划：解除连接器绑定并停用 registry 条目，已发布版本保留。');
    } catch (error) { setMessage(`软件撤销计划被拒绝：${friendlyError(error)}`); }

    },
  };
}

import {GlobalUpdatePanel} from '../../panels/global-update.jsx';
import {TaskProgress} from '../../shared/TaskProgress.jsx';
import {BodyIntakePanel} from '../../features/intake/BodyIntakePanel.jsx';
import React from 'react';
import {
  AnchorPanel,
