    {catalogDetail && <div className="catalog-detail"><div className="editor-heading"><strong>{catalogDetail.kind} / {catalogDetail.id}</strong><button className="small-button" onClick={() => setCatalogDetail(null)}>关闭详情</button></div><div className="path-line">{catalogDetail.promptPath || catalogDetail.catalogPath || catalogDetail.registryPath}</div>{catalogDetail.kind==='agent' && <div className="git-actions"><button className="primary-small" onClick={()=>setEditing({type:'agent',resourceId:catalogDetail.id})}>编辑正文／发布更新</button><button className="small-button" disabled={checking || !platformId} onClick={smoke}>{checking?'检查中…':'最小调用检查'}</button></div>}<pre>{catalogDetail.kind === 'agent' ? JSON.stringify(catalogDetail.manifest, null, 2) + '\n\n' + (catalogDetail.prompt || '') : catalogDetail.catalogText || JSON.stringify(catalogDetail.catalog, null, 2)}</pre></div>}
    {(editing || catalogDetail?.kind==='agent' || skillDetail?.selectedSkill) && <div className="wizard-field"><label>更新／检查所属平台</label><select value={platformId} onChange={event=>{setPlatformId(event.target.value);setCheckResult(null);}}><option value="">请选择平台</option>{inventory?.platforms?.map(row=><option key={row.id} value={row.id}>{row.id}</option>)}</select></div>}
    {checkResult && <div className={'scan-result '+(checkResult.ok?'clean':'warning')}>{checkResult.ok?'准备、领取、停止已通过；正文任务未执行。':checkResult.error || checkResult.issues?.join('；') || '调用未通过'}{checkResult.evidencePath && <div className="path-line">证据：{checkResult.evidencePath}</div>}</div>}
    {skillDetail?.selectedSkill && <button className="primary-small" onClick={()=>setEditing({type:'skill',resourceId:skillDetail.selectedSkill.id,version:skillDetail.selectedSkill.version})}>编辑此技能／发布更新</button>}
    {editing && <AgentSkillBodyForm api={api} workspace={workspace} platformId={platformId} resource={editing} setPlanPreview={setPlanPreview} setPlanPayload={setPlanPayload} setMessage={setMessage} onClose={()=>setEditing(null)} />}
    {skillDetail && <div className="catalog-detail"><div className="editor-heading"><strong>{skillDetail.id} 的技能条目（{skillDetail.visibleSkills?.length || 0}/{skillDetail.skillCount}）</strong><div className="panel-tools"><input className="filter-input" value={skillFilter} onChange={(event) => { setSkillFilter(event.target.value); setPage(0); }} placeholder="筛选技能 id" /><button className="small-button" onClick={() => setSkillDetail(null)}>关闭详情</button></div></div><div className="panel-tools"><button className="small-button" disabled={page === 0} onClick={() => setPage(page - 1)}>上一页</button><span className="muted">第 {page + 1} / {Math.max(1, Math.ceil((skillDetail.visibleSkills?.length || 0) / PAGE_SIZE))} 页，每页 50 条</span><button className="small-button" disabled={(page + 1) * PAGE_SIZE >= (skillDetail.visibleSkills?.length || 0)} onClick={() => setPage(page + 1)}>下一页</button></div><div className="skill-detail-list">{(skillDetail.visibleSkills || []).slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE).map((skill) => <div className="catalog-row" key={skill.id + '-' + skill.version}><span><strong>{skill.id}</strong><span className="resource-repo">v{skill.version} · {skill.sourcePath || ''}</span></span><button className="small-button" onClick={() => readSkill(skill)}>读取正文</button></div>)}</div>{skillDetail.selectedSkill && <pre>{skillDetail.selectedSkill.content}</pre>}</div>}
    {!inventory && <div className="empty">选择工作区后读取 agent registry 和 skill 目录。正文只读查看，启用/停用/移除先生成计划。</div>}
  </section>;
}

import React, { useState } from 'react';

export function ClonePanel({ api, onCloned, setMessage, friendlyError }) {
  const [remote, setRemote] = useState('');
  const [destination, setDestination] = useState('');
  const [busy, setBusy] = useState(false);
  const pickDestination = async () => {
    const selected = await api.selectDirectory();
    if (selected) setDestination(selected);
  };
  const clone = async () => {
    if (!remote || !destination) { setMessage('请填写仓库远端与目标目录。'); return; }
    if (!window.confirm(`确认克隆 ${remote} 到 ${destination}？\n\n这是创建全新工作区的授权动作；失败会清理半成品。`)) return;
    setBusy(true);
    try {
      const plan = await api.previewWorkspaceClonePlan({ remote, destination, confirmed: true });
      const applied = await api.applyWorkspaceClone({ plan });
      setMessage(`克隆完成（HEAD ${applied.head.slice(0, 12)}…），已切换到新工作区并开始首次扫描。`);
      onCloned(applied.destination);
    } catch (error) {
      setMessage(`克隆失败：${friendlyError(error)}`);
    } finally {
      setBusy(false);
    }
  };
  return <section className="panel"><div className="panel-title"><span>从 0 搭建：克隆架构仓</span><span className="muted">装好管理台 → 克隆 → 接入平台 → 开工</span></div>
    <div className="integration-form">
      <label>架构仓远端（https / git@ / 本地路径）<input value={remote} onChange={(event) => setRemote(event.target.value)} placeholder="https://github.com/…/ai-workflow-architecture-governance.git" /></label>
      <label>本机目标目录（须为空）<input value={destination} onChange={(event) => setDestination(event.target.value)} placeholder="D:\my-ai" /></label>
    </div>
    <div className="git-actions">
      <button className="small-button" onClick={pickDestination}>选择目录</button>
      <button className="small-button primary-small" onClick={clone} disabled={busy || !remote || !destination}>{busy ? '克隆中…' : '生成克隆计划并执行'}</button>
    </div>
    <div className="muted">克隆后自动校验架构标记（versions/tool/agent/software/AGENTS.md）；平台接入用下方接入向导完成。</div>
  </section>;
}

import React, { useState } from 'react';

export function DocumentPanel({ api, workspace, documentSummaries, visibleDocuments, documentFilter, setDocumentFilter, selectedDocument, documentDraft, setDocumentDraft, sensitiveConfirmed, setSensitiveConfirmed, openDocument, previewDocument, setMessage, friendlyError }) {
  const [diff, setDiff] = useState(null);
  const showDiff = async () => {
    if (!workspace || !selectedDocument) return;
    try {
      const result = await api.documentDiff({ workspaceRoot: workspace, relativePath: selectedDocument.path });
      setDiff(result);
      setMessage(result.empty ? '该文档当前没有未提交的 Git 改动。' : `已读取 ${selectedDocument.path} 的 Git 差异（只读）。`);
    } catch (error) {
      setMessage(`差异读取失败：${friendlyError(error)}`);
    }
  };
  return <section className="panel document-panel"><div className="panel-title"><span>更新日志、计划与说明文档</span><div className="panel-tools"><input className="filter-input" value={documentFilter} onChange={(event) => setDocumentFilter(event.target.value)} placeholder="搜索文件名或类型" /><span className="muted">{visibleDocuments.length}/{documentSummaries.length} 篇</span></div></div><div className="document-list">
    {visibleDocuments.map((item) => <button className="document-item" key={item.path} onClick={() => { setDiff(null); openDocument(item.path); }}><span><strong>{item.path.replace('versions/', '')}</strong><small>{item.checklistTotal ? ' · ' + item.checklistDone + '/' + item.checklistTotal + ' 项完成' : item.pItems.length ? ' · ' + item.pItems.length + ' 个 P 项' : ' · ' + item.bytes + ' 字节'}</small></span><span className="document-badges"><span className="pill">{item.kind === 'update-log' ? '更新日志' : item.kind === 'implementation-table' ? 'P表' : item.kind === 'proposal' ? '方案' : item.kind === 'ledger' ? '台账' : item.kind === 'top-level-requirements' ? '顶层要求' : '文档'}</span>{item.completionPercent != null && <span className="pill good">{item.completionPercent}%</span>}</span></button>)}
    {visibleDocuments.length === 0 && <div className="empty">{documentSummaries.length ? '没有匹配的文档。' : '选择工作区后显示更新日志、方案、P 表、台账和顶层要求。'}</div>}
  </div>{selectedDocument && <div className="editor-box"><div className="editor-heading"><strong>{selectedDocument.path}</strong><span className="muted">SHA-256 {selectedDocument.sha256.slice(0, 12)}…</span></div><textarea value={documentDraft} onChange={(event) => setDocumentDraft(event.target.value)} spellCheck={false} />{selectedDocument.sensitive && <label className="sensitive-confirm"><input type="checkbox" checked={sensitiveConfirmed} onChange={(event) => setSensitiveConfirmed(event.target.checked)} /> 我确认这是顶层治理要求的变更预览</label>}<div className="git-actions"><button className="small-button" onClick={showDiff}>查看 Git 差异</button><button className="small-button" onClick={previewDocument}>生成文档变更计划</button></div>{diff && <pre className="path-line">{diff.empty ? '（无未提交改动）' : diff.diff}</pre>}</div>}</section>;
}

import React,{useState} from 'react';
import {GitActionForm} from '../features/git/GitActionForm.jsx';

export function GitPanel({ gitDetails, workspace, refreshGit, previewGit, sensitiveScan,platforms }) {
  const [action,setAction]=useState(null);
  return <section className="panel git-panel"><div className="panel-title"><span>Git 与备份</span><span className="muted">计划预览</span></div><div className="git-summary"><div><span className="muted">分支</span><code>{gitDetails?.branch || '—'}</code></div><div><span className="muted">HEAD</span><code>{gitDetails?.head ? gitDetails.head.slice(0, 12) + '…' : '—'}</code></div><div><span className="muted">远端</span><code>{gitDetails?.upstream || gitDetails?.remotes?.[0] || '未绑定'}</code></div><div><span className="muted">同步</span><span>{gitDetails?.ahead == null ? '未设置 upstream' : 'ahead ' + gitDetails.ahead + ' · behind ' + gitDetails.behind}</span></div><div><span className="muted">改动</span><span>{gitDetails?.status?.length ?? '—'} 项</span></div></div><div className="git-actions"><button className="small-button" onClick={refreshGit} disabled={!workspace}>刷新并扫敏感文件</button><button className="small-button" onClick={() => setAction('commit')} disabled={!workspace}>提交计划（显式路径）</button><button className="small-button" onClick={() => setAction('branch')} disabled={!workspace}>分支计划</button><button className="small-button" onClick={() => setAction('tag')} disabled={!workspace}>标签计划</button><button className="small-button" onClick={() => setAction('push')} disabled={!workspace}>推送计划（禁强推）</button><button className="small-button" onClick={() => setAction('backup')} disabled={!workspace}>历史备份计划</button><button className="small-button" onClick={() => setAction('snapshot')} disabled={!workspace}>HEAD 快照导出</button><button className="small-button" onClick={() => setAction('rollback')} disabled={!workspace}>回滚计划（revert）</button></div>{action && <GitActionForm key={action} action={action} details={gitDetails} platforms={platforms} onPreview={previewGit} onClose={()=>setAction(null)} />}{sensitiveScan && <div className={sensitiveScan.clean ? 'scan-result clean' : 'scan-result warning'}>{sensitiveScan.clean ? '敏感文件扫描通过' : '发现 ' + sensitiveScan.findings.length + ' 项待核对'}<span className="muted"> · 所有计划仍需确认后执行</span></div>}{sensitiveScan?.findings?.length > 0 && <ul className="finding-list">{sensitiveScan.findings.slice(0, 8).map((finding) => <li key={finding.path + '-' + finding.kind}><code>{finding.path}</code> · {finding.kind}</li>)}</ul>}</section>;
}

import React,{useEffect,useRef,useState} from 'react';
import {friendlyError} from '../presenter.mjs';

const labels={complete:'更新并验证通过','no-change':'无变化',pending:'待补','validated-awaiting-push':'已验证，待推送',stopped:'已停止',restored:'已恢复旧接入配置','failed-restored':'失败，已恢复','external-change':'外部变化需核对','not-started':'尚未开始'};
export function GlobalUpdatePanel({api,workspace,inventory,busy,setPlanPreview,setPlanPayload,setMessage}) {
  const [settings,setSettings]=useState({}),[push,setPush]=useState(false),[working,setWorking]=useState(false),[error,setError]=useState(''),[previous,setPrevious]=useState(null),[result,setResult]=useState(null),[preflight,setPreflight]=useState(null);
  const scope=useRef(workspace);scope.current=workspace;
  useEffect(()=>{setSettings({});setPrevious(null);setResult(null);setError('');setPush(false);setPreflight(null);},[workspace]);
  useEffect(()=>{let active=true;if(workspace)api.readGlobalUpdateHistory({workspaceRoot:workspace}).then(value=>{if(active&&value){setPrevious(value.plan);setResult(value.result);}}).catch(()=>{});return()=>{active=false;};},[workspace,api]);
  useEffect(()=>{
    const receive=event=>{if(event.detail.workspaceRoot===workspace){setPrevious(event.detail.plan);setResult(event.detail.result);}};
    window.addEventListener('global-update-result',receive);return()=>window.removeEventListener('global-update-result',receive);
  },[workspace]);
  const field=(id,key,value)=>setSettings(old=>({...old,[id]:{...old[id],[key]:value}}));
  const preview=async(mode='new')=>{
    const origin=workspace;setWorking(true);setError('');
    try {
      const plan=mode==='restore'?await api.previewGlobalUpdateRestore({workspaceRoot:workspace,updatePlan:previous}):await api.previewGlobalUpdate({workspaceRoot:workspace,settings,push,...(mode==='resume'?{resumePlan:previous}:{})});
      if(scope.current!==origin)return;
      if(mode!=='restore') {
        setPreflight(plan.payload.preflight || []);
        if(plan.payload.platforms.some(row=>row.pending.some(code=>/^CONTEXT_WINDOW/.test(code)))) {setError('请在下方补填缺少的有效上下文窗口和来源，再点击一键更新重新生成计划。');return;}
      }
      setPlanPreview(plan);setPlanPayload(null);setMessage(mode==='restore'?'旧接入配置恢复计划已生成，请核对后执行。':`已有有效配置的平台更新计划已生成：${plan.target.platformIds.length} 个目标；一次确认后依次执行。`);
    }catch(value){if(scope.current===origin)setError(friendlyError(value));}finally{if(scope.current===origin)setWorking(false);}
  };
  return <section className="panel global-update-panel"><div className="panel-title"><span>所有平台的三仓接入更新</span><button className="primary-small small-button" disabled={!workspace||busy||working} onClick={()=>preview()}>一键更新所有平台</button></div>
    <p>自动纳入已有有效接入配置的平台，统一核对目标后依次更新。各平台分别保存验证与恢复记录，未配置者列为跳过。配置更新、能力地板和厂商原生工具验证分别记录。</p>
    <label className="sensitive-confirm"><input type="checkbox" checked={push} disabled={busy||working} onChange={event=>setPush(event.target.checked)} />本次同时正常推送已配置的 Git 远端；未推送时保留“已验证，待推送”</label>
    <details open={preflight?.some(row=>row.pending.some(code=>/^CONTEXT_WINDOW/.test(code))) || undefined}><summary>必要补填与保留个人固定版本</summary>{inventory?.platforms?.map(row=><div className="wizard-grid" key={row.id}><strong>{row.displayName||row.id}</strong><span>{preflight?.find(item=>item.platformId===row.id)?.pending.map(code=>friendlyError(code)).join('；') || ''}</span><label>有效上下文窗口<input type="number" min="1" placeholder={String(preflight?.find(item=>item.platformId===row.id)?.contextWindowTokens || '沿用本平台已声明值')} value={settings[row.id]?.contextWindowTokens||''} onChange={event=>field(row.id,'contextWindowTokens',event.target.value)} /></label><label>窗口来源<input value={settings[row.id]?.contextWindowSource||''} placeholder={preflight?.find(item=>item.platformId===row.id)?.contextWindowSource || '模型配置或用户确认'} onChange={event=>field(row.id,'contextWindowSource',event.target.value)} /></label><label>资源工具 Python<input value={settings[row.id]?.pythonExecutable||''} placeholder="沿用本平台解释器；缺库版本不兼容时补填" onChange={event=>field(row.id,'pythonExecutable',event.target.value)} /></label><label>保留的个人固定资源<input value={(settings[row.id]?.retain||[]).join(',')} placeholder="agent:资源ID,tool:资源ID" onChange={event=>field(row.id,'retain',event.target.value.split(',').map(value=>value.trim()).filter(Boolean))} /></label></div>)}</details>
    {error&&<div role="alert" className="notice">{error}</div>}
    {result&&<><div className="rows">{result.results?.map(row=><div className="row" key={row.platformId}><strong>{row.platformId}</strong><span>{labels[row.status]||row.status}</span><span>{row.error?friendlyError(row.error):(row.pending||[]).map(code=>friendlyError(code)).join('；')}<br />配置：{row.activated?'已更新':'未更新'}；能力地板：{row.check?.coverageComplete===true?'有验证记录':'待验证'}；厂商原生工具：{row.native?.nativeVendorClientVerified?'有真回执':'待验证'}</span></div>)}{result.skipped?.map(row=><div className="row" key={row.platformId}><strong>{row.platformId}</strong><span>跳过，先完成原接入向导：{friendlyError(row.reason)}</span></div>)}</div><div className="git-actions"><button className="small-button" disabled={busy||working} onClick={()=>preview('resume')}>继续本次更新</button><button className="small-button" disabled={busy||working} onClick={()=>preview('restore')}>恢复本次旧接入配置</button></div></>}
  </section>;
}

import React, { useEffect, useState } from 'react';

const STATUSES = ['open', 'closed', 'absorbed', 'ruled', 'unverified-registration'];
const RED = new Set(['open', 'unverified-registration']);

export function GovernancePanel({ api, workspace, setPlanPreview, setPlanPayload, setMessage, friendlyError }) {
  const [book, setBook] = useState(null);
  const [error, setError] = useState(null);
  const [check, setCheck] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [newStatus, setNewStatus] = useState('');
  const [showAppend, setShowAppend] = useState(false);
  const [draft, setDraft] = useState({ id: '', title: '', status: 'open', location: '', source: '' });
  const load = () => {
    if (!workspace) return;
    setError(null);
    api.readDefectBook(workspace).then((data) => setBook(data)).catch((e) => setError(String(e?.message ?? e)));
  };
  useEffect(() => {
    setBook(null);
    setCheck(null);
    setEditingId(null);
    setShowAppend(false);
    load();
  }, [workspace]);
  const runChecker = () => {
    if (!workspace) return;
    setMessage('正在运行缺陷簿机检（只读）……');
    api.verifyDefectBook(workspace).then((result) => {
      setCheck(result);
      setMessage(result.passed ? '缺陷簿机检通过（exit 0）。' : `缺陷簿机检未通过（exit ${result.exitCode}），见输出。`);
    }).catch((e) => setMessage(`机检运行失败：${friendlyError(e)}`));
  };
  const previewStatusChange = async () => {
    try {
      const plan = await api.previewDefectBookEditPlan({ workspaceRoot: workspace, operation: 'set-status', rowId: editingId, newStatus, baselineSha256: book.sha256 });
      setPlanPreview(plan);
      setPlanPayload(null);
      setMessage(`已生成缺陷簿状态变更计划：${plan.target.description}。尚未写入。`);
    } catch (e) {
      setMessage(`缺陷簿计划被拒绝：${friendlyError(e)}`);
    }
  };
  const previewAppend = async () => {
    try {
      const plan = await api.previewDefectBookEditPlan({ workspaceRoot: workspace, operation: 'append', row: draft, baselineSha256: book.sha256 });
      setPlanPreview(plan);
      setPlanPayload(null);
      setMessage(`已生成缺陷登记计划：${plan.target.description}。尚未写入。`);
    } catch (e) {
      setMessage(`缺陷簿计划被拒绝：${friendlyError(e)}`);
    }
  };
  return <section className="panel"><div className="panel-title"><span>治理 · 缺陷状态簿（登记走计划层）</span><div className="panel-tools"><span className="muted">{book && book.present && !book.corrupt ? `共 ${book.total} 条 · 红行 ${book.redRows.length}` : '未读取'}</span><button className="small-button" onClick={load} disabled={!workspace}>刷新</button><button className="small-button" onClick={runChecker} disabled={!workspace}>运行机检</button></div></div>
    {error && <div className="empty">读取失败：{error}</div>}
    {!book && !error && <div className="empty">选择工作区后读取 versions/缺陷状态簿.json。</div>}
    {book && book.corrupt && <div className="empty">缺陷簿不是合法 JSON，登记已阻止。</div>}
    {book && book.present && !book.corrupt && <div>
      <div className="git-summary">{STATUSES.map((status) => <div key={status}><span className={RED.has(status) && book.counts[status] > 0 ? 'pill warn' : 'muted'}>{status}</span><span> {book.counts[status] || 0}</span></div>)}</div>
      {book.redRows.length > 0 && <div className="scan-result warning">红行点名：{book.redRows.map((row) => row.id).join('、')}</div>}
      {check && <div className={check.passed ? 'scan-result clean' : 'scan-result warning'}>机检 {check.passed ? '通过' : `未通过（exit ${check.exitCode}）`}{check.output ? <pre className="path-line">{check.output.slice(-400)}</pre> : null}</div>}
      <div className="rows resource-rows">
        {book.rows.map((row) => <div className="row" key={row.id || row.title}>
          <div>
            <span className="row-name">{row.id}</span>
            <span className={RED.has(row.status) ? 'pill warn' : 'pill good'}>{row.status}</span>
            <div className="path-line">{row.title}</div>
          </div>
          <div className="resource-actions">
            {editingId === row.id
              ? <><select className="version-select" value={newStatus} onChange={(event) => setNewStatus(event.target.value)}><option value="">新状态</option>{STATUSES.filter((status) => status !== row.status).map((status) => <option key={status} value={status}>{status}</option>)}</select><button className="small-button" disabled={!newStatus} onClick={previewStatusChange}>生成变更计划</button><button className="small-button" onClick={() => { setEditingId(null); setNewStatus(''); }}>取消</button></>
              : <button className="small-button" onClick={() => { setEditingId(row.id); setNewStatus(''); setShowAppend(false); }}>变更状态</button>}
          </div>
        </div>)}
      </div>
      <div className="git-actions">
        <button className="small-button" onClick={() => { setShowAppend((value) => !value); setEditingId(null); }}>{showAppend ? '收起登记表单' : '登记新缺陷'}</button>
      </div>
      {showAppend && <div className="editor-box">
        {['id', 'title', 'location', 'source'].map((field) => <div key={field}><label className="muted">{field}</label><input className="filter-input" value={draft[field]} onChange={(event) => setDraft((state) => ({ ...state, [field]: event.target.value }))} placeholder={field} /></div>)}
        <div><label className="muted">status</label><select className="version-select" value={draft.status} onChange={(event) => setDraft((state) => ({ ...state, status: event.target.value }))}>{STATUSES.map((status) => <option key={status} value={status}>{status}</option>)}</select></div>
        <button className="small-button" onClick={previewAppend}>生成登记计划</button>
        <div className="muted">登记与状态变更都只生成计划；确认前不写任何文件。</div>
      </div>}
    </div>}
  </section>;
}

import React, { useEffect, useState } from 'react';

export function InboxPanel({ api, workspace }) {
  const [inbox, setInbox] = useState(null);
  const [error, setError] = useState(null);
  const load = () => {
    if (!workspace) return;
    setError(null);
    api.inspectInbox(workspace).then((data) => setInbox(data)).catch((e) => setError(String(e?.message ?? e)));
  };
  useEffect(() => {
    setInbox(null);
    load();
  }, [workspace]);
  return <section className="panel"><div className="panel-title"><span>inbox 盘点（纯只读）</span><div className="panel-tools"><span className="muted">BP-7：不自动发现 · 不执行 · 不删除</span><button className="small-button" onClick={load} disabled={!workspace}>刷新</button></div></div>
    {error && <div className="empty">读取失败：{error}</div>}
    {!inbox && !error && <div className="empty">选择工作区后显示三个分区。</div>}
    {inbox && <div>
      {inbox.bp7Ledger && <div className="muted">BP-7 备份账：{inbox.bp7Ledger.present ? (inbox.bp7Ledger.corrupt ? '存在但不可读' : `${inbox.bp7Ledger.entryCount} 条登记（${inbox.bp7Ledger.generatedAt || '时间未知'}）`) : '未找到'}</div>}
      {inbox.zones.map((zone) => <div key={zone.zone}>
        <div className="panel-subtitle">{zone.zone} · {zone.present ? `${zone.entryCount} 项` : '分区不存在'}</div>
        {zone.present && zone.entries.length > 0 && <div className="rows">{zone.entries.map((entry) => <div className="row" key={entry.name}>
          <div><span className="row-name">{entry.name}</span><div className="path-line">{entry.kind === 'directory' ? '目录' : '文件'}</div></div>
        </div>)}</div>}
        {zone.present && zone.entries.length === 0 && <div className="empty">空分区。</div>}
      </div>)}
    </div>}
  </section>;
}

import React from 'react';

export function IntegrationPanel({ api, workspace, resources, integrationKind, setIntegrationKind, integrationOptions, integrationTargetId, setIntegrationTargetId, integrationMode, setIntegrationMode, integrationPaths, integrationPath, setIntegrationPath, integrationTarget, setIntegrationTarget, integrationText, setIntegrationText, integrationTargetVersion, setIntegrationTargetVersion, platformSuggestion, reloadIntegrationTarget, previewIntegration, friendlyError, setMessage }) {
  const chooseTarget = (next) => {
    setIntegrationTargetId(next);
    if (next === '__registry__') setIntegrationMode('registry');
  };
  const choosePath = (next) => {
    setIntegrationPath(next);
    const selected = integrationPaths.find((item) => item === next);
    if (!selected) return;
    api.readIntegrationTarget({ workspaceRoot: workspace, kind: integrationKind, targetId: integrationTargetId, relativePath: selected })
      .then((detail) => { setIntegrationTarget(detail); setIntegrationText(detail.content || ''); })
      .catch((error) => setMessage('接入目标读取失败：' + friendlyError(error)));
  };
  return <section className="panel integration-panel">
    <div className="panel-title"><span>接入与版本向导</span><span className="muted">预览 → 确认 → 验证</span></div>
    <div className="integration-help">选好对象后，管理台会生成操作预览。平台不必手写 JSON；配置文件保存成功不代表客户端已经接通，仍需单独验证。</div>
    <div className="integration-form">
      <label>对象类型<select value={integrationKind} onChange={(event) => { const next = event.target.value; setIntegrationKind(next); setIntegrationMode(next === 'platform' ? 'config' : 'pointer'); setIntegrationTargetId(''); setIntegrationTarget(null); }}><option value="platform">platform</option><option value="tool">tool</option><option value="agent">agent</option><option value="software">software</option></select></label>
      <label>对象<select value={integrationTargetId} onChange={(event) => chooseTarget(event.target.value)}><option value="">选择对象</option>{integrationOptions.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
      {integrationKind !== 'platform' && <label>动作<select value={integrationMode} onChange={(event) => setIntegrationMode(event.target.value)}><option value="pointer">切换 current 指针</option><option value="registry">修改 registry</option></select></label>}
      {integrationKind !== 'platform' && <label>目标文件<select value={integrationPath} onChange={(event) => choosePath(event.target.value)}><option value="">选择目标</option>{integrationPaths.map((path) => <option key={path} value={path}>{path}</option>)}</select></label>}
      {integrationMode === 'pointer' && integrationTarget && <label>目标版本<select value={integrationTargetVersion} onChange={(event) => setIntegrationTargetVersion(event.target.value)}><option value="">选择已发布版本</option>{(resources.find((item) => item.repository === integrationKind && item.resourceId === integrationTargetId)?.availableVersions || []).map((version) => <option key={version} value={version}>{version}</option>)}</select></label>}
    </div>
    {integrationKind === 'platform' && platformSuggestion && <div className="integration-help">目标：{platformSuggestion.path}。{platformSuggestion.source === 'canonical' ? '已有标准配置，可继续做接通检查。' : platformSuggestion.source === 'legacy' ? '将旧配置复制到标准位置；若发现客户端仍指向旧文件，会在计划中一同迁移引用。旧文件保留。' : platformSuggestion.nextStep === 'adapter-required' ? '可生成基础配置，但缺客户端适配器；保存后仍为“待适配”。' : '已找到客户端配置，可生成标准 bridge。'}</div>}
    {integrationTarget && integrationMode !== 'pointer' && <><div className="path-line">基线 SHA-256：{integrationTarget.sha256 || '新文件'} · 目标：{integrationTarget.path}</div><textarea className="integration-editor" value={integrationText} onChange={(event) => setIntegrationText(event.target.value)} readOnly={integrationKind === 'platform'} spellCheck={false} aria-label="配置预览" /></>}
    <div className="resource-actions"><button className="small-button" onClick={reloadIntegrationTarget} disabled={!integrationTarget}>重新读取目标</button><button className="small-button primary-small" onClick={previewIntegration} disabled={!integrationTarget || (integrationKind === 'platform' && platformSuggestion?.source === 'canonical') || (integrationMode === 'pointer' ? !integrationTargetVersion : !integrationText)}>{integrationKind === 'platform' ? '预览创建 bridge.json' : '生成接入计划'}</button></div>
  </section>;
}

import {GatewayBindings} from '../shared/GatewayBindings.jsx';
import React, { useEffect, useState, useRef } from 'react';
import {useSelectionApi} from '../shared/useSelectionApi.mjs';
import {OnboardingDraft} from '../shared/onboarding-draft.mjs';

const STEPS = ['选择平台', '完整配置', '准备环境', '客户端入口', '检查与接入', '登记与恢复'];
const MODULES={configuration:'配置',backend:'隔离后端',environment:'运行环境',providers:'平台 provider',capabilities:'能力实测',client:'服务通道验证',native:'厂商原生三仓验证',software:'软件绑定',certification:'完整认证',governance:'治理登记',git:'Git 提交'};
const EMPTY = { displayName: '', pythonExecutable: '', environmentManifest: '', scriptEnvironment: '', executionBackend: '', peerDispatcherModule: '', peerContentRoot: '', softwareGateway: '', softwareEnvironment: '', clientKind: 'cli', clientExecutable: '', clientArgs: [], probeTool: '', probeArguments: {} };

export function OnboardPanel({ api, workspace, inventory, busy = false, setPlanPreview, setPlanPayload, setMessage, friendlyError }) {
  const [selection, setSelection] = useState('__new__');
  const [newId, setNewId] = useState('');
  const [step, setStep] = useState(0);
  const [confirmed, setConfirmed] = useState(false);
  const [fields, setFields] = useState(EMPTY);
  const [snapshot, setSnapshot] = useState(null);
  const [localWorking, setWorking] = useState(false);
  const working = localWorking || busy;
  const [result, setResult] = useState(null);
  const [capabilityEvidence, setCapabilityEvidence] = useState(null);
  const [nativeBodyPath,setNativeBodyPath]=useState('');
  const [native,setNative]=useState(null);
  const [localError, setLocalError] = useState('');
  const [runtime, setRuntime] = useState(null);
  const [softwareBodies, setSoftwareBodies] = useState({});
  const [softwarePython, setSoftwarePython] = useState('');
  const [deferred,setDeferred]=useState([]);
  const [backendFields, setBackendFields] = useState({ distro: '', guestInterpreter: '/usr/bin/python3', wslExecutable: '' });
  const platformId = selection === '__new__' ? newId : selection;
  const draft=useRef(new OnboardingDraft());
  const context=workspace+':'+platformId;
  api=useSelectionApi(api,context);
  const currentContext=useRef(context);currentContext.current=context;
  const editBodies=values=>{for(const key of Object.keys(values))if(values[key]!==softwareBodies[key])draft.current.edit('bodies',key);setSoftwareBodies(values);};
  const editBackend=(values,editedKey)=>{if(editedKey)draft.current.edit('backend',editedKey);for(const key of Object.keys(values))if(values[key]!==backendFields[key])draft.current.edit('backend',key);setBackendFields(values);};
  const editSoftwarePython=value=>{draft.current.edit('softwarePython');setSoftwarePython(value);};
  const input = () => ({ workspaceRoot: workspace, platformId, fields, confirmed });
  const field = (key, value) => {draft.current.edit('fields',key);setFields(old=>({...old,[key]:value}));};
  useEffect(() => {
    if (!workspace || !/^[a-z][a-z0-9-]{1,30}$/.test(platformId)) { setSnapshot(null); return; }
    const changed=draft.current.select(context),token=draft.current.begin();
    if(changed){setFields(EMPTY);setSoftwareBodies({});setSoftwarePython('');setBackendFields({distro:'',guestInterpreter:'/usr/bin/python3',wslExecutable:''});setRuntime(null);setResult(null);setSnapshot(null);setWorking(false);setCapabilityEvidence(null);setNativeBodyPath('');setNative(null);}
    let active = true;
    api.readOnboardingConfig({ workspaceRoot: workspace, platformId }).then((data) => {
      if (!active || !draft.current.accepts(token)) return;
      setSnapshot(data);setFields(old=>draft.current.merge('fields',old,data.fields));setLocalError('');
      setSoftwareBodies(old=>draft.current.merge('bodies',old,data.registeredBodies || {}));
      setBackendFields(old=>draft.current.merge('backend',old,data.backendFields || {}));
      if(draft.current.untouched('softwarePython'))setSoftwarePython(data.registeredInterpreterAliases?.PPython || '');
      if (data.pendingAutomatic) {
        const saved = data.pendingAutomatic.inputs;
        if(!data.backendFields?.distro)setBackendFields(old=>draft.current.merge('backend',old,saved.backendFields || {}));
        if(changed){setConfirmed(saved.confirmed);setDeferred(saved.deferred || []);setNativeBodyPath(saved.nativeBodyPath || '');}
        setResult({ ...data.pendingAutomatic,status: data.pendingAutomatic.status==='configured-pending'?'本轮配置已保存 · 接入未完成':`已恢复接入参数；上次停止在 ${MODULES[data.pendingAutomatic.stoppedAt] || data.pendingAutomatic.stoppedAt || '未完成步骤'}` });
      }else if(changed)setDeferred([]);
    }).catch((error) => { if (active) setLocalError(friendlyError(error)); });
    return () => { active = false; };
  }, [workspace, platformId, inventory]);
  useEffect(()=>{let active=true;if(workspace && platformId && selection!=='__new__')api.nativeClientStatus({workspaceRoot:workspace,platformId}).then(value=>{if(active)setNative(value);}).catch(()=>{});return ()=>{active=false;};},[workspace,platformId,inventory]);
  const act = async (operation, message) => {
    const identity=context;
    setWorking(true); setLocalError('');
    try {
      const value = await operation();
      if(identity!==currentContext.current)return;
      if (value?.schema === 'architecture-manager-plan/v1') { setPlanPreview(value); setPlanPayload(null); }
      else setResult(value);
      if (message) setMessage(message);
      return value;
    } catch (error) { if(identity!==currentContext.current || error.message==='STALE_TASK_RESULT')return;const text = friendlyError(error); setLocalError(text); setMessage(text); }
    finally { if(identity===currentContext.current)setWorking(false); }
  };
  const pickFile=async apply=>{try{const path=await api.selectOnboardingFile();if(path)apply(path);else setLocalError('已取消选择文件。');}catch(error){if(error.message!=='STALE_TASK_RESULT')setLocalError(friendlyError(error));}};
  const selectFile=key=>pickFile(path=>field(key,path));
  const previewAutomatic=async resumeMode=>act(async()=>{
    const latest=await api.readOnboardingConfig({workspaceRoot:workspace,platformId});
    const current=resumeMode==='reconcile'?draft.current.merge('fields',fields,latest.fields):fields;
    return api.previewAutomaticOnboardingPlan({workspaceRoot:workspace,platformId,fields:current,confirmed,backendFields,nativeBodyPath,bodies:resumeMode==='reconcile'?draft.current.merge('bodies',softwareBodies,latest.registeredBodies):softwareBodies,interpreterAliases:resumeMode==='reconcile'?{...latest.registeredInterpreterAliases,PPython:softwarePython}:{PPython:softwarePython},deferred,resumeMode});
  },'接入计划已生成；暂缓项与配置差异在预览中列出，确认前不会修改日志。');
  const run = async () => {
    if (!await api.confirm(`开始 ${platformId} 的接入检查？将使用它自己的配置和环境，保存逐步记录。没有通过的能力不会被声明为已接入。`)) return;
    return act(() => api.runOnboardingPipeline({ workspaceRoot: workspace, platformId, includeMatrix: true }), '接入执行结果已返回。');
  };
  const nativeAiProbe=async()=>{
    if(!await api.confirm('允许本次使用 WorkBuddy 原生模型验证一次吗？只允许一个只读工具读取三仓冻结文本，不执行业务、不自动重试，可能消耗厂商额度。'))return;
    return act(async()=>{const value=await api.probeNativeClientWithAi({workspaceRoot:workspace,platformId,aiConsent:true});setNative(value);return value;},'本次原生 AI 验证已返回；是否通过以真实工具回执为准。');
  };
  const fileField = (key, label) => <label className="onboarding-field" key={key}><span>{label}</span><div className="onboarding-input"><input value={fields[key] || ''} onChange={(event) => field(key, event.target.value)} /><button className="small-button" disabled={working} onClick={() => selectFile(key)}>选择文件</button></div></label>;
  return <section className="panel onboarding-panel">
    <div className="panel-title"><span>平台接入向导</span><span className="muted">配置、环境、入口与验证由管理台执行</span></div>
    {!workspace ? <div className="empty">请先选择你的架构工作区。</div> : <>
      <nav className="onboarding-steps" aria-label="接入步骤">{STEPS.map((name, index) => <button className={`small-button ${step === index ? 'primary-small' : ''}`} key={name} onClick={() => setStep(index)}>{index + 1}. {name}</button>)}</nav>
      <div className="onboarding-automatic"><strong>确认一次连续执行；暂不需要的模块可稍后补齐</strong><p>配置和安全边界必查。暂缓不会算通过，也不会显示完整接入；未满足地板时不启动完整矩阵，其它选中步骤仍可保存。</p><fieldset><legend>本次暂缓（可多选）</legend>{[['environment','运行环境与能力实测'],['software','软件本体绑定'],['client','客户端验证'],['certification','接入认证／首次矩阵'],['git','Git 提交']].map(([name,label])=><label key={name} className="sensitive-confirm"><input type="checkbox" disabled={working} checked={deferred.includes(name)} onChange={event=>setDeferred(old=>event.target.checked?[...old,name]:old.filter(item=>item!==name))} />暂缓{label}</label>)}<p>暂缓环境会连带暂缓依赖它的 provider/能力/客户端/认证；暂缓软件或客户端会连带暂缓完整认证。后续取消勾选并继续即可补齐。</p></fieldset><div className="git-actions"><button className="primary-small small-button" disabled={working || !snapshot || (selection === '__new__' && !confirmed)} onClick={()=>previewAutomatic('strict')}>预览一键接入／继续</button><button className="small-button" disabled={working || !snapshot?.exists} onClick={()=>previewAutomatic('reconcile')}>核对当前更改后续接</button><button className="small-button" disabled={working || !snapshot?.exists} onClick={()=>previewAutomatic('restart')}>预览重建接入记录</button></div>{snapshot?.resumePreview?.changes?.length>0 && <div className="notice">检测到 {snapshot.resumePreview.changes.length} 项配置更改；请用“核对当前更改后续接”。旧记录会留日期副本，受影响结果重新验证。</div>}</div>
      {snapshot?.providerTemplates && !snapshot.providerTemplates.current && <div className="notice"><strong>平台安装的组件需要更新</strong><p>旧组件不会因打开新版管理台而自动改变。确认下面的更新计划后，仅重验受影响能力。</p><button className="small-button" disabled={working || !snapshot.exists} onClick={()=>act(()=>api.previewOnboardingProvidersPlan({workspaceRoot:workspace,platformId}),'组件更新计划已生成；已有软件绑定保留。')}>预览更新已安装组件</button></div>}
      <GatewayBindings binding={snapshot?.gatewayBinding} workspace={workspace} platformId={platformId} api={api} act={act} working={working} />
      {localError && <div role="alert" className="onboarding-error">{localError}</div>}
      {step === 0 && <>
        <label className="onboarding-field"><span>操作对象</span><select value={selection} onChange={(event) => { setSelection(event.target.value); setResult(null); setConfirmed(false); }}><option value="__new__">新增平台</option>{(inventory?.platforms || []).map((item) => <option key={item.id} value={item.id}>{item.id} · 修复或升级接入</option>)}</select></label>
        {selection === '__new__' && <label className="onboarding-field"><span>平台 ID</span><input value={newId} onChange={(event) => setNewId(event.target.value.toLowerCase())} placeholder="例如 my-client" /></label>}
        <label className="onboarding-field"><span>显示名称</span><input value={fields.displayName || ''} onChange={(event) => field('displayName', event.target.value)} /></label>
        {selection === '__new__' && <label className="sensitive-confirm"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /> 允许在本工作区创建该平台一级目录</label>}
        <p className="muted">已有平台会保留原配置和运行锁；预览中列出本轮要修改的文件。</p>
        <label className="onboarding-field"><span>厂商平台本体（可自动识别本平台已有程序）</span><div className="onboarding-input"><input value={nativeBodyPath} onChange={event=>setNativeBodyPath(event.target.value)} placeholder="留空自动识别；多个程序时选择要接入的 EXE" /><button className="small-button" disabled={working} onClick={()=>pickFile(setNativeBodyPath)}>选择程序</button></div></label>
        <p className="muted">一键预览会自动探测现有兼容 Python 与 WSL；无需先手填这些路径。厂商外部接口缺失时会保存准备结果并明确等待接口。</p>
        {snapshot?.exists && <button className="small-button" disabled={working} onClick={() => act(async()=>{const data=await api.readOnboardingConfig({workspaceRoot:workspace,platformId});draft.current.dirty.clear();setSnapshot(data);setFields(data.fields);setSoftwareBodies(data.registeredBodies || {});setSoftwarePython(data.registeredInterpreterAliases?.PPython || '');setBackendFields({distro:'',guestInterpreter:'/usr/bin/python3',wslExecutable:'',...data.backendFields});setRuntime(null);setCapabilityEvidence(null); setResult({ status: '已读取当前生效配置；重新预览会保留已激活的环境，并核对新的版本与能力。' });return data;})}>重新读取当前配置（放弃未保存编辑）</button>}
      </>}
      {step === 1 && <>
        <p>目标：{platformId || '未选平台'}。三仓根路径自动取当前工作区。</p>
        {snapshot && <div className="onboarding-versions">{Object.values(snapshot.versions).map((item) => <span className="pill" key={item.id}>共享默认：{item.id} {item.version}</span>)}</div>}
        {snapshot?.performanceRecommendation && <div className="notice"><strong>可选择提速配对</strong><p>引擎 {snapshot.performanceRecommendation.runnerVersion} · 检查器 {snapshot.performanceRecommendation.scannerVersion} · 契约 {snapshot.performanceRecommendation.contractsVersion} · 调用判据 {snapshot.performanceRecommendation.matrixVersion}。选择后仍需预览并保存配置；现有默认不会自动改变。</p><button className="small-button" disabled={working} onClick={()=>Object.entries(snapshot.performanceRecommendation).forEach(([key,value])=>field(key,value))}>选择这套提速版本</button></div>}
        <label className="onboarding-field"><span>有效上下文窗口（固定提示预算依据，历史消息另计）</span><input type="number" min="1" value={fields.contextWindowTokens || ''} onChange={event=>field('contextWindowTokens',event.target.value)} /></label>
        <label className="onboarding-field"><span>窗口来源</span><input value={fields.contextWindowSource || ''} onChange={event=>field('contextWindowSource',event.target.value)} /></label>
        <label className="onboarding-field"><span>本平台资源环境清单</span><input value={fields.resourceEnvironmentManifest || ''} onChange={event=>field('resourceEnvironmentManifest',event.target.value)} /></label>
        {[['runnerVersion','wf-runner','运行引擎'],['contractsVersion','runtime-contracts','运行契约'],['scannerVersion','repo-lint','资源检查器']].map(([key,id,label]) => <label className="onboarding-field" key={key}><span>{label} · 当前使用 {snapshot?.config?.[key==='runnerVersion' ? 'runner':key==='contractsVersion' ? 'contracts':'scannerRelease']?.split(/[\\/]/).at(-1) || '未配置'}</span><select disabled={working} value={fields[key] || ''} onChange={(event)=>field(key,event.target.value || null)}><option value="">使用共享默认 {snapshot?.versions[id]?.version || ''}</option>{(inventory?.sharedRepositories?.find(repo=>repo.repository==='tool')?.pointers?.find(item=>item.resourceId===id)?.availableVersions || []).map(version=><option key={version} value={version}>{version}</option>)}</select></label>)}
        {fileField('pythonExecutable', 'Python 解释器')}
        <details><summary>高级配置：环境、委派与软件位置</summary>{[['environmentManifest', '环境清单'], ['executionBackend', '隔离后端配置'], ['peerDispatcherModule', '委派 provider'], ['softwareGateway', '软件连接器'], ['softwareEnvironment', '软件本体登记']].map(([key, label]) => fileField(key, label))}
        <label className="onboarding-field"><span>脚本环境目录</span><input value={fields.scriptEnvironment || ''} onChange={(event) => field('scriptEnvironment', event.target.value)} /></label>
        <label className="onboarding-field"><span>委派内容目录</span><input value={fields.peerContentRoot || ''} onChange={(event) => field('peerContentRoot', event.target.value)} /></label></details>
        <button className="small-button primary-small" disabled={working || !snapshot || (selection === '__new__' && !confirmed)} onClick={() => act(() => api.previewOnboardingConfigPlan(input()), '完整配置计划已生成，请核对后确认执行。')}>预览并保存完整配置</button>
      </>}
      {step === 2 && <>
        <p>所需解释器和库安装在 {platformId || '所选平台'}/runtime 内；缺少系统设施时会暂停并告诉你需要点击什么。</p>
        {fileField('pythonExecutable', '用于准备环境的 Python')}
