        {fileField('executionBackend', '本平台隔离后端配置')}
        <button className="small-button primary-small" disabled={working || !snapshot || !snapshot.exists || !api.previewOnboardingRuntimePlan} onClick={() => act(() => api.previewOnboardingRuntimePlan(input()), '环境准备计划已生成；安装前先核对下载和磁盘位置。')}>准备独立运行环境</button>
        <p className="muted">软件本体位置与 provider 可在软件中心绑定；清空路径并保存会解除该项绑定，程序文件保留，缺口会如实列出。</p>
        <details><summary>绑定软件本体与平台 provider</summary>{(inventory?.repositories?.software?.entries || inventory?.software || []).filter((entry) => entry.id && !entry.id.startsWith('_')).map((entry) => <label className="onboarding-field" key={entry.id}><span>{entry.id} 的程序文件</span><div className="onboarding-input"><input value={softwareBodies[entry.id] || ''} onChange={(event) => editBodies({ ...softwareBodies, [entry.id]: event.target.value })} /><button className="small-button" disabled={working} onClick={()=>pickFile(path=>{draft.current.edit('bodies',entry.id);setSoftwareBodies(old=>({...old,[entry.id]:path}));})}>选择文件</button></div></label>)}<label className="onboarding-field"><span>软件配方 PPython 解释器（如需要）</span><div className="onboarding-input"><input value={softwarePython} onChange={(event) => editSoftwarePython(event.target.value)} /><button className="small-button" disabled={working} onClick={()=>pickFile(editSoftwarePython)}>选择文件</button></div></label><button className="small-button" disabled={working || !snapshot?.exists} onClick={() => act(() => api.previewOnboardingProvidersPlan({ workspaceRoot: workspace, platformId, bodies: softwareBodies, interpreterAliases: {PPython:softwarePython} }), 'provider 和软件位置计划已生成；保存后仍需真实探测。')}>保存软件位置与 provider</button></details>
      </>}
      {step === 3 && <>
        <div className="notice"><strong>原生客户端接入</strong><p>先准备服务通道，再自动写入厂商支持的 MCP 配置并直接验证三仓。标准 CLI 自测通过只算服务可用。</p><label className="onboarding-field"><span>厂商程序</span><div className="onboarding-input"><input value={nativeBodyPath} onChange={event=>setNativeBodyPath(event.target.value)} placeholder={native?.profile?.bodyPath || '留空自动识别本平台程序'} /><button className="small-button" disabled={working} onClick={()=>pickFile(setNativeBodyPath)}>选择程序</button></div></label><button className="small-button primary-small" disabled={working || !snapshot?.exists} onClick={()=>act(()=>api.previewNativeClientPlan({workspaceRoot:workspace,platformId,bodyPath:nativeBodyPath}),'原生注册计划已生成；原配置有加密备份，真实调用单独判定。')}>预览注册原生客户端</button><button className="small-button" disabled={working || !native?.registered} onClick={()=>act(async()=>{const value=await api.probeNativeClient({workspaceRoot:workspace,platformId});setNative(value);return value;})}>验证原生三仓调用</button>{native?.profile?.kind==='workbuddy-cli' && <button className="small-button" disabled={working || !native?.registered} onClick={nativeAiProbe}>允许一次原生 AI 只读验证</button>}<button className="small-button" disabled={working || !snapshot?.exists} onClick={()=>act(async()=>{const value=await api.nativeClientStatus({workspaceRoot:workspace,platformId});setNative(value);return value;})}>刷新原生状态</button>{native && <p>配置注册：{native.registered?'已保存':'未注册'}；原生三仓调用：{native.nativeVendorClientVerified?'真实调用已验证':'待验证'}。{native.reason || ''}</p>}</div>
        <button className="small-button primary-small" disabled={working || !snapshot?.exists} onClick={() => act(() => api.previewOnboardingClientPlan({ workspaceRoot: workspace, platformId }), '标准 CLI 客户端和 MCP 服务安装计划已生成。')}>安装标准 CLI 客户端入口</button>
        <p>标准 CLI 入口通过真实 MCP 连接调用维护探针，无需模型生成回复。厂商原生客户端注册另行显示，不会由此标成通过。</p>
        <label className="onboarding-field"><span>客户端接口</span><select value={fields.clientKind} onChange={(event) => field('clientKind', event.target.value)}><option value="cli">JSON CLI 客户端入口</option><option value="mcp-stdio">MCP stdio 客户端入口</option><option value="manual-native">原生客户端测试回执</option></select></label>
        {fileField('clientExecutable', '客户端入口程序')}
        <label className="onboarding-field"><span>入口参数（每行一项）</span><textarea value={(fields.clientArgs || []).join('\n')} onChange={(event) => field('clientArgs', event.target.value.split('\n').filter(Boolean))} /></label>
        {fields.clientKind === 'mcp-stdio' && <label className="onboarding-field"><span>只读回环工具名</span><input value={fields.probeTool || ''} onChange={(event) => field('probeTool', event.target.value)} /></label>}
        <p className="muted">入口需返回本次随机挑战和配置摘要。连通服务与原生客户端已注册会分别显示。</p>
        <button className="small-button" disabled={working || !snapshot} onClick={() => act(() => api.previewOnboardingConfigPlan(input()), '客户端配置计划已生成。')}>保存客户端入口</button>
        <button className="small-button primary-small" disabled={working || !snapshot?.exists || !api.probeOnboardingClient} onClick={() => act(() => api.probeOnboardingClient({ workspaceRoot: workspace, platformId }), '客户端测试结果已返回。')}>测试真实客户端入口</button>
      </>}
      {step === 4 && <>
        <p>开始前请保存配置并完成环境与入口准备。首次接入执行完整矩阵；失败会停在具体步骤。</p>
        <button className="small-button" disabled={working || !snapshot?.exists} onClick={() => act(async () => { const value = await api.probeOnboardingCapabilities({ workspaceRoot: workspace, platformId }); setCapabilityEvidence(value.evidencePath); return value; }, '能力探针已返回，请查看实际通过项和缺口。')}>实测所需能力</button>
        <button className="small-button" disabled={working || !capabilityEvidence} onClick={() => act(() => api.previewOnboardingAttestationPlan({ workspaceRoot: workspace, platformId, evidencePath: capabilityEvidence }), '仅将真实通过项生成能力更新计划。')}>保存真实能力声明</button>
        <button className="small-button primary-small" disabled={working || !snapshot?.exists} onClick={run}>{working ? '接入检查中…' : '开始接入／继续检查'}</button>
        <button className="small-button" disabled={!working || !api.cancelOnboarding} onClick={() => api.cancelOnboarding({ workspaceRoot: workspace, platformId })}>停止本次接入</button>
      </>}
      {step === 5 && <>
        <p>治理文档和 Git 记录与检查证据一起保存。只有全部必需步骤通过，才显示“接入完成”。</p>
        <label className="onboarding-field"><span>Git 提交姓名（本机未配置时填写）</span><input value={fields.gitAuthorName || ''} onChange={(event) => field('gitAuthorName', event.target.value)} /></label>
        <label className="onboarding-field"><span>Git 提交邮箱</span><input value={fields.gitAuthorEmail || ''} onChange={(event) => field('gitAuthorEmail', event.target.value)} /></label>
        <button className="small-button" disabled={working || !snapshot?.exists || !api.previewOnboardingGovernancePlan} onClick={() => act(() => api.previewOnboardingGovernancePlan({ workspaceRoot: workspace, platformId }), '治理文档计划已生成。')}>预览治理登记</button>
        <button className="small-button" disabled={working || !snapshot?.exists || !api.readOnboardingState} onClick={() => act(() => api.readOnboardingState({ workspaceRoot: workspace, platformId }))}>查看接入记录与恢复点</button>
        <button className="small-button primary-small" disabled={working || !snapshot?.exists} onClick={() => act(async () => {const state=await api.readOnboardingState({workspaceRoot:workspace,platformId});return api.previewOnboardingFinalizePlan({ workspaceRoot: workspace, platformId,allowPending:state.status==='configured-pending' });}, '入库计划已生成；暂缓项不会因提交而记成接入完成。')}>提交当前配置／核验接入状态</button>
      </>}
      {result && <div className="onboarding-result" role="status"><strong>{result.status==='configured-pending'?'本轮配置已保存 · 接入未完成':result.status || result.stage || (result.stoppedAt ? `停止在：${result.stoppedAt}` : '已返回')}</strong>{(result.steps || []).map((item) => <p key={item.step}>{MODULES[item.step] || item.step}：{item.status==='deferred'?'暂缓':item.status || item.result?.stage || '已返回'} {(item.result?.issues || []).join('；')}</p>)}{(result.pending || []).map(item=><p key={item.step}>{MODULES[item.step] || item.step}：{item.reason}</p>)}{result.pendingSoftware?.length>0 && <p>尚未绑定本体：{result.pendingSoftware.map(item=>item.id).join('、')}。可在“准备环境”的软件绑定区或软件中心补齐。</p>}{result.issues?.map((issue, index) => <p key={index}>{issue}</p>)}{result.readback && <div className="notice"><p>本次接入回读：{result.readback.onboardingVerified?'当前配置与证据一致':'需更新组件或重新验证'}；业务正文未由接入检查执行。</p><p>本次提交未纳入运行产物：{result.readback.privacy.currentCommitPrivateBytesExcluded?'通过':'未确认'}。历史 runtime 入库件：{result.readback.privacy.legacyTrackedCount ?? '未知'} 项，单独登记，不能据此伪造合规通过。</p></div>}<details><summary>证据与读数</summary><pre>{JSON.stringify(result, null, 2)}</pre></details></div>}
      <div className="onboarding-footer"><button className="small-button" disabled={step === 0} onClick={() => setStep(step - 1)}>上一步</button><span>{step + 1} / {STEPS.length}</span><button className="small-button" disabled={step === STEPS.length - 1 || !platformId} onClick={() => setStep(step + 1)}>下一步</button></div>
    </>}
  </section>;
}

import React from 'react';

export function PlanPreview({ planPreview, executePlan, closePlan, planWriteKinds,busy=false }) {
  if (!planPreview) return null;
  const target = planPreview.target?.path || planPreview.target?.destination || planPreview.target?.nativeBodyPath || planPreview.target?.bodyPath || planPreview.target?.softwareId || planPreview.target?.platformIds?.join('、') || planPreview.target?.platformId || '所选对象';
  const mode = planPreview.kind === 'software-action' ? planPreview.target?.mode : null;
  const recovery=planPreview.target?.recovery,deferrals=planPreview.target?.deferrals;
  const stepNames={configuration:'配置',backend:'隔离后端',environment:'运行环境',providers:'平台 provider',capabilities:'能力实测',client:'客户端验证',certification:'完整认证',governance:'治理登记',git:'Git 提交'};
  const invalidated=[...new Set([...(recovery?.invalidatedSteps || []),...(planPreview.target?.inputInvalidatedSteps || [])])];
  return <section className="plan-preview" id="plan-preview"><div className="panel-title"><span>计划预览{planPreview.kind==='mcp-credential'?' · 凭据引用操作':planPreview.kind==='software-command'?' · 真实连接器操作':''}{mode === 'launch' ? ' · 查看启动条件' : mode === 'open-location' ? ' · 打开所在目录' : planPreview.kind === 'software-revert' ? ' · 软件撤销/停用' : ''}</span><div className="plan-buttons">{planWriteKinds.includes(planPreview.kind) && <button className="small-button primary-small" disabled={busy} onClick={executePlan}>确认并执行</button>}{mode === 'open-location' && <button className="small-button primary-small" disabled={busy} onClick={executePlan}>确认打开目录</button>}<button className="small-button" onClick={closePlan}>关闭</button></div></div><div className="plan-meta"><span>目标：{target}</span><span className="read-only-badge">尚未执行</span></div>{planWriteKinds.includes(planPreview.kind) && <div className="plan-explain">这一步将写入 {planPreview.steps?.length || 1} 项。请核对目标后再确认；管理台会检查文件是否被他人改动，并在写入后回读验证。平台“排除视图”不会删除目录。</div>}{planPreview.kind === 'integration-config' && planPreview.steps?.length > 1 && <div className="plan-explain">迁移旧 bridge 时，管理台会同时把客户端引用改到根级 bridge.json；旧文件仍保留。</div>}{planPreview.kind === 'software-recipe-publish' && <div className="plan-explain">本次只发布已验证的“版本查询”能力，并绑定所选平台连接器；发布后会做连接器健康检查和单格认证。若未通过，状态会保持“待验证”。</div>}{planPreview.kind === 'software-revert' && <div className="plan-explain">{planPreview.target?.originalAction === 'software-import' ? '撤销安置会把本体移入 inbox/trash，保留备份。发布中的配方会阻止此操作。' : '停用发布会解除连接器绑定并停用 registry 条目，已发布版本和 current.json 依不可变规则保留。'}</div>}{mode === 'open-location' && <div className="plan-explain">动作：打开所在目录。确认后只打开资源管理器，不启动软件。</div>}{mode === 'launch' && <div className="plan-explain">动作：查看启动条件。当前管理台没有连接 GUI/MCP 启动执行器，此卡只读；需要软件 provider 或人工启动，尚未启动任何进程。</div>}{planPreview.kind==='platform-onboarding' && <div className="notice"><strong>本次续接方式：{({strict:'严格续接',reconcile:'明确接纳当前更改并重新验证',restart:'重建接入记录，旧记录留档'})[recovery?.mode] || '严格续接'}</strong><p>暂缓项保持待补；配置保存成功不会被写成完整接入。</p>{Object.entries(deferrals || {}).map(([step,reason])=><p key={step}>暂缓 {({backend:'隔离后端',environment:'运行环境',software:'软件绑定',providers:'provider',capabilities:'能力实测',client:'客户端验证',certification:'完整认证',git:'Git 提交'})[step] || step}：{reason}</p>)}{recovery?.changes?.length>0 && <><p>以下变化仅在确认后接纳；受影响步骤会重新验证，不沿用旧 PASS。</p><ul>{recovery.changes.map(row=><li key={row.path}><code>{row.path}</code><div className="path-line">旧：{row.oldSha256}<br />现：{row.newSha256 || '文件缺失'}</div></li>)}</ul><p>重新验证：{invalidated.map(step=>stepNames[step] || step).join('、')}</p></>}{recovery?.versionsChanged && <p role="alert">运行引擎/契约/检查器钉版不同；须明确重建，核对后续接会拒绝换代。</p>}</div>}<details><summary>查看技术详情（文件与哈希）</summary><pre>{JSON.stringify(planPreview, null, 2)}</pre></details></section>;
}

import React,{useEffect,useState} from 'react';
import {useSelectionApi} from '../shared/useSelectionApi.mjs';
import {friendlyError} from '../presenter.mjs';
export function PlanCenterPanel({api,workspace,onOpenDocument=null}) {
  api=useSelectionApi(api,workspace);
  const [parsed,setParsed]=useState(null),[error,setError]=useState(''),[selected,setSelected]=useState(''),[page,setPage]=useState(0);
  const load=async()=>{if(!workspace)return;setError('');try{const value=await api.parseImplementationTables(workspace);setParsed(value);setSelected(previous=>value.documents.some(row=>row.path===previous)?previous:value.documents[0]?.path || '');setPage(0);}catch(error){setError(friendlyError(error));}};
  useEffect(()=>{setParsed(null);load();},[workspace]);
  const document=parsed?.documents.find(row=>row.path===selected),steps=document?.steps || [];
  return <section className="panel"><div className="panel-title"><span>计划中心（按文档表头读取）</span><button className="small-button" disabled={!workspace} onClick={load}>重新解析</button></div><p>状态以原文为准，不根据文件存在推测完成。普通或加粗 P 表、重排表头及进度表都可读取。</p>{error && <div className="scan-result warning">{error}</div>}{parsed && <><label className="wizard-field">实施表（{parsed.documents.length} 份）<select value={selected} onChange={event=>{setSelected(event.target.value);setPage(0);}}>{parsed.documents.map(row=><option key={row.path} value={row.path}>{row.path} · {row.steps.length} 步</option>)}</select></label>{document && <>{onOpenDocument && <button className="small-button" onClick={()=>onOpenDocument(document.path)}>打开全文／更新计划进度</button>}<div className="rows">{steps.slice(page*20,(page+1)*20).map((step,index)=><div className="row" key={step.id+':'+index}><div><strong>{step.id} {step.name}</strong><span className="pill">{step.status || '原文未写状态'}</span><div className="path-line">{step.duration || '原文未写时长'}</div><details><summary>子块、产物与判据</summary><p>子块：{step.blocks || '未声明'}</p><p>产物：{step.artifacts || '未声明'}</p><p>判据：{step.criteria || '此表未声明判据，请读正式方案'}</p></details></div></div>)}</div><div className="git-actions"><button className="small-button" disabled={!page} onClick={()=>setPage(value=>value-1)}>上一页</button><span>{page+1} / {Math.max(1,Math.ceil(steps.length/20))}</span><button className="small-button" disabled={(page+1)*20>=steps.length} onClick={()=>setPage(value=>value+1)}>下一页</button></div></>}</>}{parsed?.documents.length===0 && <p>当前 versions/ 没有可识别的 P 表。</p>}</section>;
}

import React,{useEffect,useRef,useState} from 'react';
import {friendlyError} from '../presenter.mjs';
import {useSelectionApi} from '../shared/useSelectionApi.mjs';

export function PlatformResourceVersions({api,workspace,inventory,resources,setPlanPreview,setPlanPayload,setMessage}){
  const [platformId,setPlatformId]=useState(''),[view,setView]=useState(null),[targets,setTargets]=useState({}),[filter,setFilter]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const scope=workspace+':'+platformId,current=useRef(scope);current.current=scope;api=useSelectionApi(api,scope);
  useEffect(()=>{setTargets({});setView(null);setError('');setBusy(false);},[scope]);
  useEffect(()=>{let active=true;if(!workspace||!platformId)return;api.readPlatformResourceVersions({workspaceRoot:workspace,platformId}).then(value=>{if(active)setView(value);}).catch(error=>{if(active&&error.message!=='STALE_TASK_RESULT')setError(friendlyError(error));});return ()=>{active=false;};},[workspace,platformId,inventory]);
  const preview=async(row,version)=>{const selectedScope=scope;setBusy(true);setError('');try{const plan=await api.previewPlatformResourceDefault({workspaceRoot:workspace,platformId,repository:row.repository,resourceId:row.resourceId,targetVersion:version});if(current.current!==selectedScope)return;setPlanPreview(plan);setPlanPayload(null);setMessage(`已生成 ${platformId} 的独立选版计划，其他平台和共享默认不变。`);}catch(error){if(current.current===selectedScope&&error.message!=='STALE_TASK_RESULT')setError(friendlyError(error));}finally{if(current.current===selectedScope)setBusy(false);}};
  const visible=(view?.rows || []).filter(row=>!filter||`${row.repository}/${row.resourceId}`.toLowerCase().includes(filter.toLowerCase()));
  return <section className="panel"><div className="panel-title"><span>平台独立版本</span><span className="muted">只影响所选平台后续任务</span></div><div className="wizard-grid"><label>选择平台<select value={platformId} onChange={event=>setPlatformId(event.target.value)}><option value="">请选择平台</option>{inventory?.platforms?.map(row=><option key={row.id} value={row.id}>{row.displayName || row.id}</option>)}</select></label><label>筛选 tool／agent<input value={filter} onChange={event=>setFilter(event.target.value)} placeholder="资源 ID" /></label></div><p>平台选择优先于共享默认；agent 内部的精确依赖锁与正在运行的任务不改变。“恢复跟随共享默认”清除本平台选择。</p>{error&&<div className="scan-result warning" role="alert">{error}</div>}{!platformId&&<div className="empty">先选择平台，再为它设置版本。</div>}<div className="rows resource-rows">{visible.map(row=>{const key=row.repository+'/'+row.resourceId,versions=resources.find(value=>value.repository===row.repository&&value.resourceId===row.resourceId)?.availableVersions || [],selected=targets[key] ?? row.effectiveVersion;return <div className="row resource-row" key={key}><div><span className="row-name">{row.resourceId}</span><span className="resource-repo">{row.repository}</span><div className="path-line">共享默认：{row.sharedVersion} · 平台选择：{row.platformVersion || '跟随共享默认'}<br />当前生效：{row.effectiveVersion}（{row.resolvedFrom==='platform-local'?'平台独立选择':'共享默认'}）{row.pairedVersion&&<><br />引擎配对锁定：{row.pairedVersion}；换代请用平台对齐计划。</>}</div></div><div className="resource-actions"><select value={selected} disabled={busy||Boolean(row.pairedVersion)} onChange={event=>setTargets(value=>({...value,[key]:event.target.value}))}>{versions.map(version=><option key={version} value={version}>{version}{version===row.effectiveVersion?' · 当前生效':''}</option>)}</select><button className="small-button" disabled={busy||!selected||selected===row.platformVersion||Boolean(row.pairedVersion)} onClick={()=>preview(row,selected)}>预览本平台切换／回退</button><button className="small-button" disabled={busy||!row.platformVersion||Boolean(row.pairedVersion)} onClick={()=>preview(row,null)}>恢复跟随共享默认</button></div></div>;})}</div></section>;
}

