  'missing-directory': '缺平台目录', 'missing-bridge': '缺 bridge.json', 'bridge-conflict': '配置冲突',
  'invalid-bridge': '配置有误', 'adapter-required': '待适配', 'invalid-runner-config': '客户端配置有误',
