export function ResourcePanel({api,workspace, inventory, resources, resourceFilter, setResourceFilter, targetVersions, setTargetVersions, previewResource,setPlanPreview,setPlanPayload,setMessage }) {
  const [editing,setEditing]=useState(null),[platformId,setPlatformId]=useState(inventory?.platforms?.[0]?.id || ''),[result,setResult]=useState(null),[working,setWorking]=useState(false);
  const check=async resource=>{setWorking(true);setResult(null);try{if(!await api.confirm('仅运行这个工作流的准备、领取、停止链路，不执行阶段业务。'))return;setResult(await api.checkSharedBody({workspaceRoot:workspace,platformId,type:'tool',resourceId:resource.resourceId,version:resource.version}));}catch(error){setResult({ok:false,error:friendlyError(error)});}finally{setWorking(false);}};
  const visible = resources.filter((resource) => !resourceFilter || (resource.repository + '/' + resource.resourceId).toLowerCase().includes(resourceFilter.toLowerCase()));
